    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds: integer nanoseconds
    :param tz: optional timezone information (datetime.tzinfo, string or None)
    :return: datetime.time
    """
    # convert nanoseconds to a time of day
    ns_in_day = 86_400_000_000_000
    ns_in_hour = 3_600_000_000_000
    ns_in_minute = 60_000_000_000
    ns_in_second = 1_000_000_000
    ns_in_microsecond = 1_000

