    hour = nanoseconds // ns_in_hour
    nanoseconds %= ns_in_hour
    minute = nanoseconds // ns_in_minute
    nanoseconds %= ns_in_minute
    second = nanoseconds // ns_in_second
    nanoseconds %= ns_in_second
    microsecond = nanoseconds // ns_in_microsecond

    # handle timezone if provided
    tzinfo = None
