    sec, ns_rem = divmod(ns_total, 1_000_000_000)
    # hours, minutes, seconds
    h, rem = divmod(sec, 3600)
    m, s = divmod(rem, 60)
    us = ns_rem // 1000  # drop remaining ns, keep microseconds
    if tz is None:
        return datetime.time(int(h), int(m), int(s), int(us))
    else:
        return datetime.time(int(h), int(m), int(s), int(us), tzinfo=tz)

