        return wrapper
    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    def decorator(func):
        cache = collections.OrderedDict()

        @wraps(func)
        def wrapper(*args, **kwargs):
            kwargs_tuples = tuple(sorted(kwargs.items()))
            if typed:
                key = args + tuple(type(a) for a in args) + kwargs_tuples + tuple(type(v) for k, v in kwargs_tuples)
            else:
                key = args + kwargs_tuples
            if key in cache:
                cache.move_to_end(key)
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            cache.move_to_end(key)
            if len(cache) > maxsize:
                cache.popitem(last=False)
            return result

        wrapper.cache = cache
        return wrapper

    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """

    if maxsize < 0:
        raise ValueError("maxsize must be >= 0")

    def decorator(func):
        key_cache = {}
        order = []

        def make_key(args, kwargs):
            if typed:
                types = tuple(type(arg) for arg in args)
                kwtypes = tuple((k, type(v)) for k, v in sorted(kwargs.items()))
                return (args, kwtypes, types)
            else:
                kwsorted = tuple(sorted(kwargs.items()))
                return (args, kwsorted)

        def wrapper(*args, **kwargs):
            k = make_key(args, kwargs)
            if k in key_cache:
                # Move to end to mark as most recently used
                try:
                    order.remove(k)
                except ValueError:
                    pass
                order.append(k)
                return key_cache[k]
