            key_cache[k] = result
            order.append(k)
            if len(order) > maxsize:
                oldest = order.pop(0)
                try:
                    del key_cache[oldest]
                except KeyError:
                    pass
            return result

        wrapper.cache_info = lambda: (len(key_cache), maxsize, len(order))
        return wrapper

    return decorator

