    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.
    """
    # If called without parentheses (e.g. @lru_cache) `maxsize` will be the
    # function being decorated. Detect that case and apply the standard
    # functools.lru_cache with default arguments before wrapping.
    if callable(maxsize) and isinstance(typed, bool):
        fn = maxsize
        return functools.lru_cache()(fn)
    def decorator(fn):
