def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    def decorator(func):
        cache = {}
        freq = {}
        def make_key(*args, **kwargs):
            if typed:
                # Include types in the key to avoid type clashes
                return (args, tuple(sorted(kwargs.items())),
                        tuple(type(v) for v in args),
                        tuple(type(v) for v in kwargs.values()))
            else:
                return (args, tuple(sorted(kwargs.items())))
        def wrapper(*args, **kwargs):
            key = make_key(*args, **kwargs)
            if key in cache:
                freq[key] += 1
                return cache[key]
            # call the underlying function
            result = func(*args, **kwargs)
            if len(cache) >= maxsize:
                # Evict the least frequently used entry
                min_freq = min(freq.values())
                candidates = [k for k, f in freq.items() if f == min_freq]
                evict_key = candidates[0]  # arbitrary choice among ties
                del cache[evict_key]
                del freq[evict_key]
            cache[key] = result
            freq[key] = 1
            return result
        # Preserve wrapper metadata
        wrapper.__name__ = func.__name__
        wrapper.__module__ = func.__module__
        wrapper.__doc__ = func.__doc__
        return wrapper
    return decorator

