def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    result = []
    for cls in classes:
        # Skip this base if it's a superclass of any other base in the list
        if any(issubclass(other, cls) and other is not cls for other in classes):
            continue
        result.append(cls)
    return result

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    minimal = []
    seen = set()
    for cls in classes:
        if not isinstance(cls, type):
            raise TypeError(f"Element {cls!r} is not a class")
        if cls in seen:
            continue
        # Determine if any other class in the list is a subclass of this one
        keep = True
        for other in classes:
            if other is cls:
                continue
            if issubclass(other, cls):
                # `cls` is a superclass of `other`; it is redundant
                keep = False
                break
        if keep:
            minimal.append(cls)
            seen.add(cls)
    return minimal

def namesAndDescriptions(self, all=False): # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    attrs = []

    # Function to collect from a single class
    def collect_from(cls):
        for name, obj in cls.__dict__.items():
            # Skip private or dunder attributes and methods
            if name.startswith('_'):
                continue
            if callable(obj):
                continue
            # Use the docstring of the attribute object if available
            desc = getattr(obj, "__doc__", None)
            if desc is None:
                desc = ""
            attrs.append((name, desc.strip()))

    if all:
        # Include attributes from all base classes in the MRO, skip 'object'
        for base in self.__class__.__mro__:
            if base is object:
                continue
            collect_from(base)
    else:
        # Only collect from the concrete class itself
        collect_from(self.__class__)

    # Remove duplicates while preserving order: keep first occurrence
    seen = set()
    unique_attrs = []
    for name, desc in attrs:
        if name not in seen:
            seen.add(name)
            unique_attrs.append((name, desc))

    # Sort by attribute name for consistent order
    unique_attrs.sort(key=lambda x: x[0].lower())
    return unique_attrs

