            classes.extend([c for c in self.__class__.__mro__[1:] if c is not object])
        for cls in classes:
            for name, value in cls.__dict__.items():
                if name.startswith('_'):
                    continue
                if callable(value):
                    continue
                if name in attrs:
                    continue
                desc = getattr(value, '__doc__', '') or ''
                attrs[name] = desc
