def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset any stored context to an empty dictionary.
    self.context = {}

    # Reinitialize the bin contents.
    if hasattr(self, "initial_value"):
        # If an explicit initial value is set for each bin, use it.
        # Preserve the existing number of bins.
        self.bins = [self.initial_value] * len(self.bins)
    elif hasattr(self, "make_bins") and callable(self.make_bins):
        # If no explicit initial value, ask the object to regenerate its bins.
        self.bins = self.make_bins()

    # Reset auxiliary bookkeeping if it exists.
    if hasattr(self, "counts"):
        self.counts = [0] * len(self.bins)
    if hasattr(self, "total_count"):
        self.total_count = 0
    if hasattr(self, "min_value"):
        self.min_value = None
    if hasattr(self, "max_value"):
        self.max_value = None
    if hasattr(self, "start_time_stamp_msec"):
        self.start_time_stamp_msec = None
    if hasattr(self, "end_time_stamp_msec"):
