def to_csv(self, separator=",", header=None):
        """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
              Iterables are converted to tables.

        Convert graph's points to CSV.

        *separator* delimits values, the default is comma.

        *header*, if not ``None``, is the first string of the output
        (new line is added automatically).

        Since a graph can be multidimensional,
        for each point first its coordinate is converted to string
        (separated by *separator*), then each part of its value.

        To convert :class:`Graph` to CSV inside a Lena sequence,
        use :class:`lena.output.ToCSV`.
        """
        lines = []
        if header is not None:
            lines.append(header)
        point_iter = getattr(self, "points", self)
        for point in point_iter:
            # Extract coordinate
            try:
                coord = point.coordinate
            except AttributeError:
                try:
                    coord = point[0]
                except Exception:
                    coord = point
            # Extract value
            try:
                val = point.value
            except AttributeError:
                try:
                    val = point[1]
                except Exception:
                    val = None
            # Convert coordinate parts to string
            if hasattr(coord, "__iter__") and not isinstance(coord, (str, bytes)):
                coord_str = separator.join(map(str, coord))
            else:
                coord_str = str(coord)
            # Convert value parts to string
            if val is None:
                val_str = ""
            elif hasattr(val, "__iter__") and not isinstance(val, (str, bytes)):
                val_str = separator.join(map(str, val))
            else:
                val_str = str(val)
            # Combine parts
            if coord_str and val_str:
                line = coord_str + separator + val_str
            else:
                line = coord_str or val_str
            lines.append(line)
        return "\n".join(lines)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Error indices are expected to be stored as a dictionary mapping
    # coordinate names to arrays / lists of indices.
    err_indices = getattr(self, "err_indices", None)
    if err_indices is None:
        raise AttributeError(
            "The object does not have an 'err_indices' attribute."
        )
    if coord_name not in err_indices:
        raise KeyError(
            f"Coordinate name '{coord_name}' not found in err_indices."
        )
    return err_indices[coord_name]

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Attempt to get the error index mapping from known attributes
    err_map = None
    if hasattr(self, "_err_indices") and isinstance(self._err_indices, dict):
        err_map = self._err_indices
    elif hasattr(self, "errors") and isinstance(self.errors, dict):
        err_map = self.errors
    # Return the indices for the requested coordinate, or an empty list if not found
    if err_map is not None:
        return err_map.get(coord_name, [])
    return []

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Attempt to find an error mask in common attributes.
    # First look for a dedicated dictionary.
    if hasattr(self, "_coord_errs") and isinstance(self._coord_errs, dict):
        err_arr = self._coord_errs.get(coord_name)
    else:
        err_arr = None

    # Fallback to a generic `errors` attribute.
    if err_arr is None and hasattr(self, "errors"):
        errors_attr = self.errors
        if isinstance(errors_attr, dict):
            err_arr = errors_attr.get(coord_name)
        else:
            err_arr = None

    if err_arr is None:
        raise AttributeError(
            f"No error array found for coordinate {coord_name}."
        )

    # Normalise to a numpy array for easier handling.
    try:
        import numpy as np
    except ImportError:  # pragma: no cover
        np = None

    if np is not None and isinstance(err_arr, np.ndarray):
        if err_arr.dtype == bool:
            return np.where(err_arr)[0]
        # Treat non‑zero values as errors
        return np.where(err_arr != 0)[0]

    # For non‑numpy iterables, interpret truthy values as errors.
    if hasattr(err_arr, "__iter__") and not isinstance(err_arr, (str, bytes)):
        return [i for i, val in enumerate(err_arr) if val]
    if isinstance(err_arr, bool):
        return [0] if err_arr else []

    # If we can’t determine the type, raise an informative error.
    raise TypeError(
        f"Unsupported error array type for coordinate {coord_name}: "
        f"{type(err_arr).__name__}"
    )

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    return self._err_indices.get(coord_name, [])

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element or contains at least one such,
    and it is not a Source sequence.
    """
    # Exclude Source sequences
    if isinstance(seq, SourceSequence):
        return False

    # If seq itself is a FillRequest element
    if isinstance(seq, FillRequest):
        return True

    # Avoid treating strings or bytes as iterables for this check
    if isinstance(seq, (str, bytes)):
        return False

    # Check iterable contents for a FillRequest element
    try:
        iterator = iter(seq)
    except TypeError:
        return False

    for item in iterator:
        if isinstance(item, FillRequest):
            return True
    return False

