    is_source_seq = globals().get('is_source_seq', lambda _: False)
    FillRequest = globals().get('FillRequest', object)

    if is_source_seq(seq):
        return False

    if isinstance(seq, FillRequest):
        return True

    # Attempt to iterate over seq to find any FillRequest instances
    try:
        for item in seq:
            if isinstance(item, FillRequest):
