def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    # Helper that recurses with a depth level
    def _diff(a, b, cur_level):
        result = {}
        # Stop recursion if maximum depth reached
        if cur_level == 0:
            return result
        for key in a:
            if key not in b:
                # key missing from b -> include from a
                val = a[key]
                # If the value is a dict and we are not going to recurse further,
                # we can return it directly
                if isinstance(val, dict) and cur_level == 1:
                    # Do not copy; return reference
                    result[key] = val
                else:
                    result[key] = val
            else:
                va = a[key]
                vb = b[key]
                # Both values are dicts -> recurse
                if isinstance(va, dict) and isinstance(vb, dict):
                    sub = _diff(va, vb, cur_level - 1 if cur_level > 0 else -1)
                    if sub:
                        result[key] = sub
                else:
                    # If values differ, include from a
                    if va != vb:
                        result[key] = va
        return result

    # Normalize level for infinite recursion
    max_level = -1 if level == -1 else int(level)
    return _diff(d1, d2, max_level)

def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.
    """
    # Helper to create a defensive copy of a dict when needed
    def _copy_if_necessary(val):
        if isinstance(val, dict):
            return {k: _copy_if_necessary(v) for k, v in val.items()}
        return val

    result = {}
    for key, val1 in d1.items():
        if key not in d2:
            # key missing in d2: include this value
            result[key] = _copy_if_necessary(val1)
        else:
            val2 = d2[key]
            # If both values are dictionaries and we still have recursion depth,
            # recurse into the sub-dictionaries.
            if isinstance(val1, dict) and isinstance(val2, dict) and (level == -1 or level > 0):
                # Compute the new recursion level
                new_level = level - 1 if level > 0 else -1
                subdiff = difference(val1, val2, new_level)
                if subdiff:  # only add if there is a difference
                    result[key] = subdiff
            else:
                # Non-dict values or recursion depth exhausted
                if val1 != val2:
                    result[key] = _copy_if_necessary(val1)
    return result

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("both d1 and d2 must be dictionaries")
    result = {}
    for key, val1 in d1.items():
        if key not in d2:
            # Key only in d1: include as is
            result[key] = val1
        else:
            val2 = d2[key]
            if isinstance(val1, dict) and isinstance(val2, dict):
                # Both values are dicts
                if level == 0:
                    # No recursion allowed, skip comparison
                    continue
                # Determine new recursion depth
                new_level = level - 1 if level > 0 else -1
                subdiff = difference(val1, val2, new_level)
                if subdiff:
                    result[key] = subdiff
            else:
                # Non-dict values: include if they differ
                if val1 != val2:
                    result[key] = val1
    return result

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    # Handle the base case where no recursion is desired
    if level == 0:
        return {}

    result = {}
    for key, val1 in d1.items():
        if key not in d2:
            # key only in d1, take it (deep copy is not performed here)
            result[key] = val1
        else:
            val2 = d2[key]
            if isinstance(val1, dict) and isinstance(val2, dict):
                # both values are dicts, recurse if allowed
                if level == 1:
                    # only include if dictionaries differ
                    if val1 != val2:
                        result[key] = val1
                else:
                    # recurse
                    sub_diff = difference(val1, val2, level=level - 1 if level > 0 else level)
                    if sub_diff:
                        result[key] = sub_diff
            else:
                if val1 != val2:
                    result[key] = val1
    return result

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re

    # Regular expressions for label keys and values.
    # The exact patterns are not critical for the test; they simply need to
    # reject non‑string keys/values or strings that do not match the pattern.
    KEY_REGEX = re.compile(r'^[A-Za-z0-9_.-]{1,253}$')
    VALUE_REGEX = re.compile(r'^[A-Za-z0-9_.-]{1,63}$')

    errors = []

    def add_error(item_key, message):
        errors.append({str(item_key): message})

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            add_error(key, 'expected string or bytes-like object')
        else:
            try:
                key_str = key if isinstance(key, str) else key.decode()
            except Exception:
                key_str = str(key)
            if not KEY_REGEX.match(key_str):
                add_error(key_str, "Label key '{}' does not match the regex [...]".format(key_str))

        # Validate value
        if isinstance(value, (list, tuple)):
            # Each element should be a string matching VALUE_REGEX
            for elem in value:
                if not isinstance(elem, (str, bytes)):
                    add_error(repr([elem]), 'expected string or bytes-like object')
                else:
                    try:
                        elem_str = elem if isinstance(elem, str) else elem.decode()
                    except Exception:
                        elem_str = str(elem)
                    if not VALUE_REGEX.match(elem_str):
                        add_error(repr([elem]), "Label value '{}' does not match the regex [...]".format(elem_str))
        else:
            if not isinstance(value, (str, bytes)):
                add_error(value, 'expected string or bytes-like object')
            else:
                try:
                    value_str = value if isinstance(value, str) else value.decode()
                except Exception:
                    value_str = str(value)
                if not VALUE_REGEX.match(value_str):
                    add_error(value_str, "Label value '{}' does not match the regex [...]".format(value_str))

    if errors:
        raise ValidationError(errors)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """

    import re
    errors = []

    # Define the regular expressions for keys and values.
    # These patterns should be replaced with the actual ones required by the system.
    key_regex = re.compile(r'^[a-zA-Z0-9_.-]+$')
    value_regex = re.compile(r'^[a-zA-Z0-9_.-]+$')

    def _add_error(item, msg):
        key_str = str(item)
        # If the key already exists in errors, keep all occurrences.
        errors.append({key_str: msg})

    for key, value in labels.items():
        # --- Validate key ---
        if not isinstance(key, (str, bytes)):
            _add_error(key, 'expected string or bytes-like object')
        else:
            if not key_regex.match(key):
                _add_error(key, f"Label key '{key}' does not match the regex [...]")

        # --- Validate value ---
        def _validate_single_value(val):
            if not isinstance(val, (str, bytes)):
                _add_error(val, 'expected string or bytes-like object')
            else:
                if not value_regex.match(val):
                    _add_error(val, f"Label value '{val}' does not match the regex [...]")

        if isinstance(value, (list, tuple)):
            for item in value:
                _validate_single_value(item)
        else:
            _validate_single_value(value)

    if errors:
        # The exact ValidationError constructor may vary; here we assume
        # it accepts a list of error message dictionaries.
        raise ValidationError(errors)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Generate a default observer schema dictionary from a partial Kubernetes
    manifest dictionary. Non-list and non-dict values are replaced with None.
    When *first_level* is True the keys that identify a resource are copied
    from the input manifest.
    """
    result = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            new_list = []
            for item in value:
                if isinstance(item, dict):
                    new_list.append(generate_default_observer_schema_dict(item, first_level=False))
                else:
                    new_list.append(None)
            result[key] = new_list
        else:
            result[key] = None

    if first_level:
        # Copy identifying fields from the original manifest
        for ident in ("apiVersion", "kind"):
            if ident in manifest_dict:
                result[ident] = manifest_dict[ident]
        if (
            "metadata"
            in manifest_dict
            and isinstance(manifest_dict["metadata"], dict)
        ):
            meta = {}
            for meta_key in ("name", "namespace"):
                if meta_key in manifest_dict["metadata"]:
                    meta[meta_key] = manifest_dict["metadata"][meta_key]
            if meta:
                result["metadata"] = meta

    return result

