def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Ensure the application has a `spec` attribute.
    if not hasattr(app, "spec"):
        return
    spec = app.spec

    # Ensure the manifest exists.
    if not hasattr(spec, "manifest"):
        return

    # Prepare a container for observer schemas if it does not already exist.
    if not hasattr(spec, "observer_schema"):
        spec.observer_schema = {}

    # Iterate over all resources in the manifest.
    for resource_id, resource_def in spec.manifest.items():
        # Skip if an explicit observer schema is already defined on the resource.
        if isinstance(resource_def, dict) and resource_def.get("observer_schema"):
            continue

        # If a schema for this resource already exists (perhaps from a previous
        # call or a custom specification), skip creating a new one.
        if resource_id in spec.observer_schema:
            continue

        # Create a simple default observer schema.  This schema captures the
        # `metadata` and `status` sections of a typical Kubernetes object.
        default_schema = {
            "metadata": {
                "uid": str,
                "name": str,
                "namespace": str,
            },
            "status": {
                "phase": str,  # most resources expose a `phase` field
            },
        }

        # Store the generated schema.
        spec.observer_schema[resource_id] = default_schema

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Retrieve the current observers dictionary (if any)
    observers = getattr(app.spec, "observers", {})
    if observers is None:
        observers = {}

    # Iterate over all Kubernetes objects defined in the application's manifest
    manifest = getattr(app.spec, "manifest", [])
    for resource in manifest:
        if not isinstance(resource, dict):
            continue  # skip any non‑dict entries
        kind = resource.get("kind")
        if not kind:
            continue  # skip resources without a kind

        # If no custom observer schema is defined for this kind, create a simple default
        if kind not in observers:
            observers[kind] = {"type": "object"}

    # Store the updated observers back on the application spec
    setattr(app.spec, "observers", observers)
    return observers

