def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Ensure digests_used is a set for efficient lookup
    digests_used_set = set(digests_used)
    # Use the internal digests mapping (assuming it is stored in self._digests)
    digests_available = getattr(self, "_digests", {})
    missing = []
    unused = []
    for file_entry in manifest_files:
        digest = file_entry.get("digest")
        if not digest:
            continue
        # Check that the digest is in the known digests
        if digest not in digests_available:
            missing.append(digest)
        # Check that the digest is actually used
        if digest not in digests_used_set:
            unused.append(digest)
    if missing:
        raise ValueError(f"Missing digests in manifest: {', '.join(missing)}")
    if unused:
        raise ValueError(f"Digests in manifest were not marked as used: {', '.join(unused)}")

def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""
        # determine set of needed digests from manifest
        if isinstance(manifest_files, dict):
            needed = set(manifest_files.keys())
        else:
            # assume iterable of digests
            needed = set(manifest_files)

        used = set(digests_used)

        missing = sorted(needed - used)
        unused = sorted(used - needed)

        if missing:
            raise RuntimeError(f"The following digests are required by the manifest but were not used: {missing}")

        if unused:
            raise RuntimeError(f"The following digests were used but are not referenced in the manifest: {unused}")

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Gather all digests that appear in the manifest
    manifest_digests = set()
    for mf in manifest_files:
        if hasattr(mf, 'digest'):
            manifest_digests.add(mf.digest)

    # Digests that are used but not found in the manifest
    missing_in_manifest = digests_used - manifest_digests
    if missing_in_manifest:
        missing_str = ', '.join(sorted(missing_in_manifest))
        raise ValueError(f"Used digests missing from manifest: {missing_str}")

    # Digests present in manifest but not marked as used (optional warning)
    unused_in_use = manifest_digests - digests_used
    if unused_in_use:
        # If a logger is available, emit a warning; otherwise silently ignore
        if hasattr(self, 'logger'):
            msg = f"Digests present in manifest but not used: {', '.join(sorted(unused_in_use))}"
            self.logger.warning(msg)

    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Ensure `manifest_files` is a mapping of filename -> digest string.
    if not hasattr(manifest_files, '__iter__'):
        raise TypeError("manifest_files must be iterable of (filename, digest) pairs")

    # Convert digests_used to set for efficient lookup.
    used_set = set(digests_used)

    missing_files = []
    for entry in manifest_files:
        if isinstance(entry, (tuple, list)) and len(entry) == 2:
            filename, digest = entry
        elif isinstance(entry, dict):
            # Expect dict with 'filename' and 'digest' keys
            filename = entry.get('filename')
            digest = entry.get('digest')
            if filename is None or digest is None:
                raise ValueError(f"Malformed manifest entry: {entry}")
        else:
            raise ValueError(f"Unrecognized manifest entry type: {entry}")

        if digest not in used_set:
            missing_files.append(filename)

    if missing_files:
        raise ValueError(f"Missing digests for files: {', '.join(missing_files)}")

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    missing = []
    unexpected = []

    # Expect manifest_files to be a mapping of filename -> digest
    for filename, digest in manifest_files.items():
        if digest not in digests_used:
            missing.append((filename, digest))

    # Ensure that every used digest actually appears in the manifest
    for digest in digests_used:
        if digest not in manifest_files.values():
            unexpected.append(digest)

    if missing or unexpected:
        msgs = []
        if missing:
            msgs.append(
                "Missing digests for files: " +
                ", ".join(f"{fn} (digest={dg})" for fn, dg in missing)
            )
        if unexpected:
            msgs.append(
                "Unexpected digests used that are not in the manifest: " +
                ", ".join(unexpected)
            )
        raise ValueError("; ".join(msgs))
    return None

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure the prior is an instance of the same validator class
    if not isinstance(prior, self.__class__):
        raise TypeError(f"prior must be an instance of {self.__class__.__name__}")

    # Compare version numbers if available
    if hasattr(self, "version") and hasattr(prior, "version"):
        try:
            if prior.version >= self.version:
                raise ValueError(
                    f"Prior inventory version ({prior.version}) must be less than "
                    f"current inventory version ({self.version})"
                )
        except TypeError:
            # If the version attributes are not comparable, skip the check
            pass

    # Ensure the names (or identifiers) match if defined
    if hasattr(self, "name") and hasattr(prior, "name"):
        if self.name != prior.name:
            raise ValueError(
                f"Prior inventory name '{prior.name}' does not match current name '{self.name}'"
            )

    # Helper: extract a flat dictionary of non‑private, non‑callable attributes
    def _flatten(obj):
        flat = {k: v for k, v in vars(obj).items() if not k.startswith("_") and not callable(v)}
        # If there is an explicit 'inventory' dict, use it as the representation
        if "inventory" in flat and isinstance(flat["inventory"], dict):
            return flat["inventory"]
        return flat

    # Get the dictionaries representing each inventory
    cur_dict = _flatten(self)
    prior_dict = _flatten(prior)

    # Every key/value pair in the prior must exist and match in the current inventory
    for key, val in prior_dict.items():
        if key not in cur_dict:
            raise ValueError(
                f"Key '{key}' present in prior inventory but missing from current inventory."
            )
        if cur_dict[key] != val:
            raise ValueError(
                f"Value for key '{key}' differs between prior and current inventories.\n"
                f"Prior: {val!r}\nCurrent: {cur_dict[key]!r}"
            )

    # If we reach here, the prior inventory is a valid earlier version
    return None

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    errors = []
    # Make sure prior is of the same type
    if not isinstance(prior, type(self)):
        errors.append(TypeError(
            f"prior must be an instance of {type(self).__name__}"
        ))
        return errors

    # Ensure we can compare versions
    if not hasattr(prior, "version") or not hasattr(self, "version"):
        errors.append(AttributeError(
            "Both current and prior objects must have a 'version' attribute"
        ))
        return errors

    # Prior must be older than current
    if prior.version >= self.version:
        errors.append(ValueError(
            f"prior version ({prior.version}) must be older than current version ({self.version})"
        ))

    # Check that the two inventories contain the same set of keys
    if hasattr(self, "inventory") and hasattr(prior, "inventory"):
        curr_keys = set(self.inventory.keys())
        prior_keys = set(prior.inventory.keys())
        if curr_keys != prior_keys:
            errors.append(ValueError(
                f"Inventory keys differ between current and prior: "
                f"current={curr_keys}, prior={prior_keys}"
            ))
        else:
            # Compare corresponding items for equality or compatibility
            for key in curr_keys:
                curr_item = self.inventory[key]
                prior_item = prior.inventory[key]
                # If items have an 'is_compatible_with' method, use it
                if hasattr(curr_item, "is_compatible_with"):
                    compatible = curr_item.is_compatible_with(prior_item)
                    if not compatible:
                        errors.append(
                            ValueError(
                                f"Inventory item '{key}' is not compatible between current and prior"
                            )
                        )
                else:
                    # Fallback to simple equality check
                    if curr_item != prior_item:
                        errors.append(
                            ValueError(
                                f"Inventory item '{key}' differs between current and prior"
                            )
                        )
    else:
        errors.append(AttributeError(
            "Both current and prior must have an 'inventory' attribute")
        )
    return errors

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Resolve underlying mapping of entities for both prior and current inventories
    prior_map = getattr(prior, 'entities', None)
    if prior_map is None:
        prior_map = getattr(prior, 'inventory', None)
    if prior_map is None:
        prior_map = getattr(prior, 'elements', None)
    if prior_map is None:
        raise TypeError("prior object does not expose an inventory mapping")

    current_map = getattr(self, 'entities', None)
    if current_map is None:
        current_map = getattr(self, 'inventory', None)
    if current_map is None:
        current_map = getattr(self, 'elements', None)
    if current_map is None:
        raise TypeError("current inventory object does not expose an inventory mapping")

    for name, prior_entity in prior_map.items():
        # Entity must exist in current inventory
        if name not in current_map:
            raise ValueError(f"Entity {name!r} from prior is missing in the current inventory")
        curr_entity = current_map[name]

        # Types must match
        if type(prior_entity) != type(curr_entity):
            raise TypeError(
                f"Entity {name!r} type mismatch: prior ({type(prior_entity).__name__}) "
                f"vs current ({type(curr_entity).__name__})"
            )

        # If entities carry metadata with a version tag, ensure the current
        # inventory has an equal or newer version
        prior_meta = getattr(prior_entity, 'metadata', getattr(prior_entity, '__dict__', {}))
        if isinstance(prior_meta, dict) and 'version' in prior_meta:
            curr_meta = getattr(curr_entity, 'metadata', getattr(curr_entity, '__dict__', {}))
            if isinstance(curr_meta, dict):
                curr_version = curr_meta.get('version')
                prior_version = prior_meta.get('version')
                if curr_version is None:
                    raise ValueError(f"Entity {name!r} missing version in current inventory")
                if curr_version < prior_version:
                    raise ValueError(
                        f"Entity {name!r} has older version ({curr_version}) than prior ({prior_version})"
                    )
    # No errors imply the prior is a valid prior version of the current inventory.

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # If the inventory or requested version is not present, return an empty map
    if not inventory or version not in inventory:
