def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    def get(item, name):
        # Try dictionary key first, then attribute
        try:
            return item[name]
        except (TypeError, KeyError):
            return getattr(item, name, None)

    # First collect all mappings for the requested version (or earlier)
    logical_map = {}
    for item in inventory:
        v = get(item, "version")
        if v is None:
            continue
        # treat version string comparison; convert to tuple of ints for simple ordering
        def parse(vstr):
            return tuple(int(part) for part in str(vstr).split(".") if part.isdigit())
        if parse(v) <= parse(version):
            lp = get(item, "logical_path")
            cf = get(item, "content_file")
            if lp is None or cf is None:
                continue
            logical_map.setdefault(lp, set()).add(cf)

    # Build a reverse index from content_file to logical_paths
    content_index = {}
    for lp, files in logical_map.items():
        for cf in files:
            content_index.setdefault(cf, set()).add(lp)

    # Now look for duplicates in later versions
    for item in inventory:
        v = get(item, "version")
        if v is None:
            continue
        if parse(v) > parse(version):
            cf = get(item, "content_file")
            if cf is None:
                continue
            if cf in content_index:
                # Add this content_file to all logical paths that already reference it
                for lp in content_index[cf]:
                    logical_map[lp].add(cf)

    return logical_map

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

