                            continue
                    if ver is not None and f is not None and ver <= version:
                        files.add(f)
            if files:
                path_map[logical_path] = files

    # Case 2: inventory is a mapping of version -> dict of logical_path -> set(file)
    # Attempt to locate the appropriate version and collapse its mapping.
    else:
        # Find exact match or the closest lower version
        target = None
        for v in inventory:
            if v == version:
                target = inventory[v]
                break
        if target is None:
            # Try to find the greatest version less than or equal to requested
            valid = [v for v in inventory if v <= version]
            if valid:
                target = inventory[max(valid)]
        if target:
            for logical_path, files in target.items():
                path_map[logical_path] = set(files)

    return path_map

