def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        # Normalize the manifest to a set for fast lookup
        manifest_set = set(manifest_files)

        # Resolve the list of entries from the fixity block
        if isinstance(fixity, dict):
            # Prefer the 'files' key if present, otherwise the dict itself
            entries = fixity.get('files', fixity)
            if not isinstance(entries, list):
                raise ValueError("The fixity block dict must contain a list of file entries (via 'files').")
        elif isinstance(fixity, list):
            entries = fixity
        else:
            raise ValueError("The fixity block must be a list or a dict with a 'files' key containing a list.")

        seen_files = set()
        for idx, entry in enumerate(entries, start=1):
            if not isinstance(entry, dict):
                raise ValueError(f"Fixity entry #{idx} is not a dict.")
            # Required fields
            for field in ('filename', 'checksum', 'checksum_algorithm'):
                if field not in entry:
                    raise ValueError(f"Missing required field '{field}' in fixity entry #{idx}.")
            # The filename must exist in the manifest
            filename = entry['filename']
            if filename not in manifest_set:
                raise ValueError(f"Fixity entry #{idx} references unknown file '{filename}'.")
            # No duplicate entries for the same file
            if filename in seen_files:
                raise ValueError(f"Duplicate fixity entry for file '{filename}'.")
            seen_files.add(filename)

        # All entries are valid
        return True

