        if fname not in manifest_set:
            raise ValueError(f"File '{fname}' referenced in fixity block is not present in the manifest")

        # The hash entry for each file must itself be a dictionary
        if not isinstance(hash_dict, dict):
            raise ValueError(f"Checksum entry for file '{fname}' must be a dictionary")

        if not hash_dict:
            raise ValueError(f"No hash information provided for file '{fname}'")

        for alg, hash_val in hash_dict.items():
            # Algorithm names should be strings
            if not isinstance(alg, str):
                raise ValueError(f"Algorithm name for file '{fname}' must be a string")

            # Hash values should be strings
            if not isinstance(hash_val, str):
                raise ValueError(f"Hash value for algorithm '{alg}' in file '{fname}' must be a string")

            # Optionally, check that the algorithm is one of the supported types
            allowed_algorithms = {"SHA-256", "SHA-1", "MD5", "SHA-512", "CRC32"}
            if alg.upper() not in allowed_algorithms:
                raise ValueError(f"Unsupported hash algorithm '{alg}' in file '{fname}'")

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    for filename, checksum in fixity.items():
        if not isinstance(filename, str):
            raise ValueError(
                f"Fixity key must be a string, got {type(filename).__name__}"
            )
        if filename not in manifest_files:
            raise ValueError(
                f"File '{filename}' referenced in fixity not listed in manifest"
            )
        if not isinstance(checksum, str) or not checksum:
            raise ValueError(
                f"Checksum for '{filename}' must be a non-empty string"
            )

