def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    indent_str = " " * indent

    def recurse(obj, level=0):
        ind = " " * level
        if isinstance(obj, dict):
            items = []
            for key, val in obj.items():
                items.append(f"{key!r}: {recurse(val, level + 2)}")
            return "{\n" + ind + "  " + ",\n" + ind + "  ".join(items) + "\n" + ind + "}"
        elif isinstance(obj, (list, tuple)):
            items = [recurse(item, level + 2) for item in obj]
            opening, closing = ("[", "]") if isinstance(obj, list) else ("(", ")")
            return opening + "\n" + ind + "  " + ",\n".join(items) + "\n" + ind + closing
        elif hasattr(obj, "__dict__") and not isinstance(obj, type):
            attrs = {
                k: getattr(obj, k)
                for k in dir(obj)
                if not k.startswith("_") and not callable(getattr(obj, k))
            }
            items = [f"{k}={recurse(v, level + 2)}" for k, v in attrs.items()]
            return f"{obj.__class__.__name__}(\n" + ind + "  " + ",\n".join(items) + "\n" + ind + ")"
        else:
            return repr(obj)

    representation = recurse(self, indent)
    if debug:
        return f"{indent_str}<Debug: {self.__class__.__name__} at {hex(id(self))}>\n{representation}"
    return representation

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def _simplify(expr):
        # Recursively simplify subexpressions
        if isinstance(expr, (list, tuple)):
            if len(expr) == 3 and isinstance(expr[0], str) and expr[0] in ('&', '|'):
                left = _simplify(expr[1])
                right = _simplify(expr[2])
                op = expr[0]
                # Absorption: A & (A | B) = A, A | (A & B) = A
                if op == '&' and isinstance(right, (list, tuple)) and len(right) == 3 and right[0] == '|':
                    if left == right[1]:
                        return left
                if op == '|' and isinstance(right, (list, tuple)) and len(right) == 3 and right[0] == '&':
                    if left == right[1]:
                        return left
                # Negative absorption: A & (~A | B) = A & B
                if op == '&' and isinstance(right, (list, tuple)) and len(right) == 3 and right[0] == '|':
                    if (isinstance(right[1], (list, tuple)) and len(right[1]) == 2
                        and right[1][0] == '~' and left == right[1][1]):
                        # A & (~A | B) => A & B
                        return ('&', left, right[2])
                # Negative absorption: A | (~A & B) = A | B
                if op == '|' and isinstance(right, (list, tuple)) and len(right) == 3 and right[0] == '&':
                    if (isinstance(right[1], (list, tuple)) and len(right[1]) == 2
                        and right[1][0] == '~' and left == right[1][1]):
                        # A | (~A & B) => A | B
                        return ('|', left, right[2])
                return (op, left, right)
            elif len(expr) == 2 and isinstance(expr[0], str) and expr[0] == '~':
                return ('~', _simplify(expr[1]))
        return expr

    return [_simplify(arg) for arg in args]

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified hook.
    """
    def decorator(func):
        if not hasattr(self, "_registry"):
            self._registry = {}
        self._registry.setdefault(hook, []).append(func)
        return func
    return decorator

