        'full': '{major}.{minor}.{patch}{pre_release}{build_metadata}',
        'normal': '{major}.{minor}.{patch}',
        'short': '{major}.{minor}',
        'meta'  : '{major}.{minor}.{patch}{pre}{build}',
    }

    # Resolve the format string
    fmt = presets.get(style, style)

    # Build a context dictionary with all provided pieces.
    # Missing keys are replaced with an empty string.
    ctx = {}
    for key in ('major', 'minor', 'patch', 'pre_release',
                'build_metadata', 'pre', 'build', 'commit'):
        val = pieces.get(key, '')
