            val = ''
        ctx[key] = val

    # Attempt formatting; fall back to stripping unknown placeholders.
    try:
        return fmt.format(**ctx)
    except KeyError as exc:
        # Unseen placeholder: replace it with an empty string and retry.
        missing = exc.args[0]
        ctx[missing] = ''
        return fmt.format(**ctx)

