    # Execute the command
    process = subprocess.Popen(
        cmd,
        cwd=cwd,
        stdout=subprocess.PIPE,
        stderr=stderr_option,
        env=env
    )
    stdout, stderr = process.communicate()

    # Decode output for readability
    try:
        stdout_text = stdout.decode() if stdout else ''
    except Exception:
        stdout_text = str(stdout)
    try:
        stderr_text = stderr.decode() if stderr else ''
    except Exception:
        stderr_text = str(stderr)

    if process.returncode != 0:
        raise subprocess.CalledProcessError(
            returncode=process.returncode,
            cmd=cmd,
            output=stdout_text,
            stderr=stderr_text,
        )

    return stdout_text

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import shlex

    # Build the command list
    if isinstance(commands, str):
        cmd = shlex.split(commands)
    else:
        cmd = list(commands)

    if args:
        if isinstance(args, str):
            cmd += shlex.split(args)
        else:
            cmd += list(args)

    # Verbose output
    if verbose:
        print('Running command:', ' '.join(cmd))

    # Decide on stderr handling
    stderr_target = subprocess.DEVNULL if hide_stderr else subprocess.PIPE

    # Execute the command
    try:
        proc = subprocess.Popen(
            cmd,
            cwd=cwd,
            stdout=subprocess.PIPE,
            stderr=stderr_target,
            env=env,
            text=True
        )
        stdout, stderr = proc.communicate()
    except FileNotFoundError as exc:
        raise RuntimeError(f"Command not found: {cmd[0]}") from exc
    except Exception as exc:
        raise RuntimeError(f"Failed to run command: {cmd}") from exc

    return {
        'returncode': proc.returncode,
        'stdout': stdout,
        'stderr': stderr
    }

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if isinstance(commands, str):
        cmd = [commands]
    else:
        cmd = list(commands)
    cmd.extend(args)

    if verbose:
        print('Running command: {}'.format(' '.join(cmd)))

    stderr = subprocess.DEVNULL if hide_stderr else None

    # Merge user-provided environment with the current environment
    if env is not None:
        final_env = os.environ.copy()
        final_env.update(env)
    else:
        final_env = None

    try:
        output = subprocess.check_output(
            cmd,
            cwd=cwd,
            env=final_env,
            stderr=stderr
        )
        return output.decode()
    except subprocess.CalledProcessError as exc:
        # Re-raise the exception with additional context if needed
        raise exc

