def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        # Gather all objects from the hierarchy
        try:
            objects = list(self._enumerate_objects())
        except AttributeError:
            # Fallback if no dedicated enumerator is defined
            objects = list(self.root.iteratesubobjects()) if hasattr(self, 'root') else []

        num_objects = 0
        good_objects = 0
        warnings = []

        for obj in objects:
            num_objects += 1
            valid = True
            # Validate object structure and contents if requested
            if validate_objects:
                try:
                    valid &= self._validate_object(obj)
                except Exception as exc:
                    valid = False
                    warnings.append(f"Validation error for object {obj}: {exc}")

            # Check digest/hash integrity if requested
            if check_digests:
                try:
                    valid &= self._check_digest(obj)
                except Exception as exc:
                    valid = False
                    warnings.append(f"Digest check failed for object {obj}: {exc}")

            if valid:
                good_objects += 1
            elif show_warnings:
                print(f"Object {obj} failed validation: {'valid' if valid else 'invalid'}")

        if show_warnings and warnings:
            for w in warnings:
                print("WARNING:", w)

        return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        (num_objects, good_objects) - number of objects checked, number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Attempt to iterate over the hierarchy; look for a method that yields objects.
    # If none exists, silently skip validation.
    iterator = getattr(self, 'iter_hierarchy', lambda: iter([]))()
    for obj in iterator:
        num_objects += 1
        is_valid = True

        # Validate the object itself if requested
        if validate_objects:
            try:
                # Assume objects have a validate() method that raises on failure
                obj.validate()
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"[WARN] Validation failed for {obj!r}: {exc}")

        # Check digests if requested
        if check_digests and is_valid:
            try:
                # Assume objects expose a `calculate_digest()` and a `stored_digest`
                calculated = getattr(obj, "calculate_digest", lambda: None)()
                stored = getattr(obj, "stored_digest", None)
                if calculated != stored:
                    is_valid = False
                    if show_warnings:
                        print(f"[WARN] Digest mismatch for {obj!r}: expected {stored!r}, got {calculated!r}")
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"[WARN] Digest check failed for {obj!r}: {exc}")

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Counters for traversal results
    num_objects = 0
    good_objects = 0

    # Recursive walker that inspects an object and its descendants
    def _walk(obj):
        nonlocal num_objects, good_objects
        num_objects += 1
        is_valid = True

        # Object‑specific validation
        if validate_objects:
            try:
                if hasattr(obj, "validate") and callable(obj.validate):
                    obj.validate()
                if hasattr(obj, "is_valid") and callable(obj.is_valid):
                    is_valid = is_valid and obj.is_valid()
            except Exception:
                is_valid = False

        # Digest check
        if check_digests and hasattr(obj, "path") and hasattr(obj, "digest"):
            try:
                import os, hashlib
                if os.path.isfile(obj.path):
                    with open(obj.path, "rb") as fp:
                        file_bytes = fp.read()
                    checksum = hashlib.md5(file_bytes).hexdigest()
                    if checksum != obj.digest:
                        is_valid = False
            except Exception:
                is_valid = False

        if is_valid:
            good_objects += 1

        # Recurse into children if they exist
        if hasattr(obj, "children") and isinstance(obj.children, (list, tuple)):
            for child in obj.children:
                _walk(child)

    # Determine the starting point of the hierarchy
    root_candidate = None
    for attr in ("hierarchy_root", "root", "storage_root", "root_node"):
        if hasattr(self, attr):
            root_candidate = getattr(self, attr)
            break

    if root_candidate is None:
        # No recognizable hierarchy entry – return zero counts
        return 0, 0

    # Kick off traversal
    _walk(root_candidate)

    # Optional warning display
    if show_warnings and num_objects > good_objects:
        print(f"Hierarchy validation completed: {good_objects}/{num_objects} objects valid, "
              f"{num_objects - good_objects} invalid.")

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Walk through the storage root directory tree
    for root_dir, dirs, files in os.walk(self.storage_root):
        # Validate each file as an object
        for filename in files:
            num_objects += 1
            file_path = os.path.join(root_dir, filename)
            is_valid = True

            # Perform optional object-specific validation
            if validate_objects:
                try:
                    # If the class provides a helper to load objects from a file,
                    # use it; otherwise default to a simple read check.
                    if hasattr(self, "object_from_path"):
                        obj = self.object_from_path(file_path)
                        if hasattr(obj, "validate"):
                            is_valid = bool(obj.validate())
                        else:
                            with open(file_path, "rb"):
                                pass  # file is readable
                    else:
                        with open(file_path, "rb"):
                            pass
                except Exception as exc:
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: validation failed for {file_path}: {exc}")

            # Optionally check the digest of the file
            if is_valid and check_digests:
                try:
                    if hasattr(self, "check_digest"):
                        digest_ok = bool(self.check_digest(file_path))
                    else:
                        # default: read the file and compute a trivial checksum
                        with open(file_path, "rb") as f:
                            digest_ok = hashlib.sha256(f.read()).hexdigest() is not None
                    is_valid = digest_ok
                except Exception as exc:
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: digest check failed for {file_path}: {exc}")

            if is_valid:
                good_objects += 1

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    def walk(node):
        nonlocal num_objects, good_objects
        num_objects += 1

        if not validate_objects:
            good_objects += 1
            return

        if hasattr(node, 'validate'):
            try:
                node.validate(check_digests=check_digests, show_warnings=show_warnings)
                good_objects += 1
            except Exception as exc:
                if show_warnings:
                    print(f"Validation failed for {node}: {exc}")
        else:
            good_objects += 1

        for child in getattr(node, 'children', []):
            walk(child)

    root = getattr(self, 'root', None)
    if root is None:
        return 0, 0

    walk(root)
    return num_objects, good_objects

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return ""
    # Detect if the version string is numeric with leading zeros
    has_leading_zeros = version.isdigit() and len(version) > 1 and version.startswith("0")
    try:
        number = int(version)
    except ValueError:
        # If the string cannot be converted to an integer, return it unchanged
        return version
    next_number = number + 1
    if has_leading_zeros:
        # Preserve the original padding length
        return str(next_number).zfill(len(version))
    return str(next_number)

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return ''
    v = version.strip()
    if not v.isdigit():
        return v
    zero_prefixed = v.startswith('0')
    incremented = str(int(v) + 1)
    if zero_prefixed:
        width = len(v)
        return incremented.zfill(width)
    return incremented

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return "1"
    if not version.isdigit():
        # Attempt to convert to int; if fails, append '1' as fallback.
        try:
            return str(int(version) + 1)
        except ValueError:
            return version + "1"
    # Handle digit-only versions
    if version.startswith("0"):
        # Zero-prefixed: preserve leading zeros when possible
        num = int(version)
        new_num = num + 1
        new_str = str(new_num)
        if len(new_str) < len(version):
            new_str = new_str.zfill(len(version))
        return new_str
    else:
        # Non-zero-prefixed: simple integer increment
        return str(int(version) + 1)

