def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    # Group values by key string while preserving first key node occurrence
    key_groups = {}
    for k_node, v_node in nodes:
        key_str = k_node.value
        if key_str not in key_groups:
            key_groups[key_str] = {'key_node': k_node, 'values': []}
        key_groups[key_str]['values'].append(v_node)

    def _merge_value_nodes(vnodes):
        if all(isinstance(v, ruamel.yaml.nodes.MappingNode) for v in vnodes):
            return _merge_mapping_nodes(vnodes)
        return vnodes[-1]  # last wins for non-mapping values

    def _merge_mapping_nodes(map_nodes):
        # Merge list of MappingNode objects into one
        inner_groups = {}
        for m in map_nodes:
            for k_node, v_node in m.value:
                key_str = k_node.value
                if key_str not in inner_groups:
                    inner_groups[key_str] = {'key_node': k_node, 'values': []}
                inner_groups[key_str]['values'].append(v_node)

        merged_pairs = []
        for g in inner_groups.values():
            merged_val = _merge_value_nodes(g['values'])
            merged_pairs.append((g['key_node'], merged_val))

        return ruamel.yaml.nodes.MappingNode(tag=map_nodes[0].tag, value=merged_pairs)

    result = []
    for g in key_groups.values():
        merged_value = _merge_value_nodes(g['values'])
        result.append((g['key_node'], merged_value))

    return result

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    from collections import OrderedDict

    def _merge_values(val1, val2):
        if isinstance(val1, MappingNode) and isinstance(val2, MappingNode):
            merged_items = deep_merge_nodes(val1.value + val2.value)
            return MappingNode(val1.tag, merged_items)
        return val2

    merged = OrderedDict()
    key_node_map = {}

    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged:
            merged[key] = _merge_values(merged[key], value_node)
        else:
            merged[key] = value_node
            key_node_map[key] = key_node

    result = [(key_node_map[k], merged[k]) for k in key_node_map]
    return result

def parser_flags(parser):
    """Given an argparse.ArgumentParser instance, return its argument flags in a space-separated string."""
    flags = []
    seen = set()
    for action in parser._actions:
        for flag in action.option_strings:
            if flag not in seen:
                seen.add(flag)
                flags.append(flag)
    return ' '.join(flags)

