def deep_merge_nodes(nodes):
    """
    Deep merge a list of (ScalarNode, value) tuples, merging duplicate
    MappingNode values recursively. For non-mapping values the last
    value wins. The order of first occurrences of keys is preserved.
    """
    def _merge_tuples(list1, list2):
        # Merge two lists of (key_node, value_node) tuples.
        result = list1[:]
        index = {k_node.value: i for i, (k_node, _) in enumerate(result)}
        for k_node, v_node in list2:
            key = k_node.value
            if key in index:
                i = index[key]
                _, existing_v = result[i]
                if hasattr(existing_v, 'value') and hasattr(v_node, 'value'):
                    # Assume both are mapping nodes.
                    merged_list = _merge_tuples(existing_v.value, v_node.value)
                    existing_v.value = merged_list
                    result[i] = (result[i][0], existing_v)
                else:
                    # Last value wins
                    result[i] = (result[i][0], v_node)
            else:
                result.append((k_node, v_node))
                index[key] = len(result) - 1
        return result

    merged = {}
    result_list = []

    for key_node, value_node in nodes:
        key = key_node.value
        if key not in merged:
            merged[key] = (key_node, value_node)
            result_list.append((key_node, value_node))
        else:
            existing_key_node, existing_value = merged[key]
            if hasattr(existing_value, 'value') and hasattr(value_node, 'value'):
                # both are mapping nodes; merge their contents
                merged_list = _merge_tuples(existing_value.value, value_node.value)
                existing_value.value = merged_list
                merged[key] = (existing_key_node, existing_value)
                # No change to result_list order
            else:
                # Last value wins
                merged[key] = (existing_key_node, value_node)
                # Update the entry in result_list
                for i, (ek, _) in enumerate(result_list):
                    if ek.value == key:
                        result_list[i] = (existing_key_node, value_node)
                        break

    return result_list

def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples
    in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    deep merge any node values corresponding to duplicate keys and return the
    result. If there are colliding keys with non-MappingNode values (e.g.,
    integers or strings), the last of the values wins.
    """
    def is_mapping(node):
        """Return True if node appears to be a MappingNode."""
        return hasattr(node, "value") and isinstance(node.value, list)

    def merge_mapping(a_node, b_node):
        """Merge two MappingNode values; a_node is updated in place."""
        # Build a dict from a_node mapping for quick lookup
        a_dict = {k_node.value: (k_node, v_node) for k_node, v_node in a_node.value}
        for k_b, v_b in b_node.value:
            key = k_b.value
            if key in a_dict:
                k_a, v_a = a_dict[key]
                # Recursively merge the values
                new_val = merge_values(v_a, v_b)
                a_dict[key] = (k_a, new_val)
            else:
                # New key from b_node
                a_dict[key] = (k_b, v_b)
        # Reconstruct the list of pairs preserving original order
        new_list = []
        seen = set()
        for k_a, v_a in a_node.value:
            new_list.append((k_a, v_a))
            seen.add(k_a.value)
        for key, (k_node, v_node) in a_dict.items():
            if key not in seen:
                new_list.append((k_node, v_node))
        a_node.value = new_list
        return a_node

    def merge_values(a, b):
        """Merge two values a and b; return the merged value."""
        if is_mapping(a) and is_mapping(b):
            return merge_mapping(a, b)
        # Non-mapping: last wins
        return b

    # Collect the merged values keyed by scalar value
    merged_map = {}
    key_nodes = {}
    for key_node, val_node in nodes:
        key = key_node.value
        if key in merged_map:
            merged_map[key] = merge_values(merged_map[key], val_node)
        else:
            merged_map[key] = val_node
            key_nodes[key] = key_node

    # Build the resulting list preserving first-encounter order
    result = []
    for key_node, _ in nodes:
        key = key_node.value
        if key in key_nodes:
            result.append((key_nodes[key], merged_map[key]))
            del key_nodes[key]
    return result

