def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    subparser_results = {}
    unknown_sets = []

    for name, parser in subparsers.items():
        namespace, unknown = parser.parse_known_args(unparsed_arguments)
        subparser_results[name] = namespace
        unknown_sets.append(set(unknown))

    if unknown_sets:
        remaining_set = set.intersection(*unknown_sets)
        remaining_arguments = [arg for arg in unparsed_arguments if arg in remaining_set]
    else:
        remaining_arguments = list(unparsed_arguments)

    return subparser_results, remaining_arguments

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """

    def _generator():
        for i in range(0, len(response), max_results):
            yield response[i:i + max_results]

    return _generator()

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.strip()
    if not size:
        raise ValueError("size string is empty")

    num_str = ""
    unit_str = ""
    for ch in size:
        if ch.isdigit() or ch == ".":
            num_str += ch
        else:
            unit_str += ch

    if not num_str:
        raise ValueError(f"no numeric value found in '{size}'")

    try:
        num = float(num_str)
    except ValueError as exc:
        raise ValueError(f"invalid numeric value '{num_str}'") from exc

    unit = unit_str.upper().strip()
    multiplier = 1
    if unit in ("B", "BYTE", "BYTES", ""):
        multiplier = 1
    elif unit.startswith("K"):
        multiplier = 1000
    elif unit.startswith("M"):
        multiplier = 1000 ** 2
    elif unit.startswith("G"):
        multiplier = 1000 ** 3
    elif unit.startswith("T"):
        multiplier = 1000 ** 4
    elif unit.startswith("P"):
        multiplier = 1000 ** 5
    elif unit.startswith("E"):
        multiplier = 1000 ** 6

    result = int(round(num * multiplier))
    return result

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        for k, v in d.items():
            result[k] = result.get(k, 0) + v
    return result

