def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not url:
        return ''

    import re
    import urllib.parse

    def _replace(match):
        key = match.group(1)
        if key in url_args:
            value = url_args[key]
            return urllib.parse.quote(str(value)) if value is not None else ''
        return match.group(0)

    pattern = r'{([^}]+)}'
    return re.sub(pattern, _replace, url)

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    # Nothing to replace
    if not url or not url_args:
        return url

    # Replace occurrences of {key} with the corresponding value from url_args
    # Values are URL‑encoded to keep the URL valid.
    import re
    import urllib.parse

    def _replace(match):
        key = match.group(1)
        if key in url_args:
            value = url_args[key]
            # Treat None as empty string
            if value is None:
                value = ''
            return urllib.parse.quote_plus(str(value))
        # If key not provided, leave placeholder unchanged
        return match.group(0)

    # Example pattern matches {key}
    pattern = r'\{([^}]+)\}'
    return re.sub(pattern, _replace, url)

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url:
        return ''

    if not url_args:
        return url

    import re
    pattern = re.compile(r'\{([^}]+)\}')

    def repl(m):
        key = m.group(1)
        return str(url_args.get(key, m.group(0)))

    return pattern.sub(repl, url)

