def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        raise ValueError("negative numbers are not supported")
    base = len(alphabet)
    if base < 2:
        raise ValueError("alphabet must contain at least two characters")
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        n = number
        while n:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])
        digits = list(reversed(digits))
    if padding is not None:
        if padding < 0:
            raise ValueError("padding must be non-negative")
        if len(digits) < padding:
            digits = [alphabet[0]] * (padding - len(digits)) + digits
    return "".join(digits)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        raise ValueError("number must be non-negative")

    base = len(alphabet)
    if base < 2:
        raise ValueError("alphabet must contain at least two symbols for a base conversion")

    # Special case for zero
    if number == 0:
        s = alphabet[0]
    else:
        digits = []
        n = number
        while n:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])
        s = ''.join(reversed(digits))

    # Pad if requested
    if padding is not None:
        if not isinstance(padding, int) or padding < 0:
            raise ValueError("padding must be a non-negative integer or None")
        if len(s) < padding:
            pad_char = alphabet[0]
            s = pad_char * (padding - len(s)) + s

    return s

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        raise ValueError("number must be non-negative")
    base = len(alphabet)
    if base < 2:
        raise ValueError("alphabet must contain at least two characters")
    # Handle zero explicitly
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        n = number
        while n:
            digits.append(alphabet[n % base])
            n //= base
        digits.reverse()
    if padding is not None:
        if padding < 0:
            raise ValueError("padding must be non-negative")
        if len(digits) < padding:
            digits = [alphabet[0]] * (padding - len(digits)) + digits
    return ''.join(digits)

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    # Helper to recursively process nested structures
    def _transform(obj):
        if isinstance(obj, dict):
            new_dict = {}
            for k, v in obj.items():
                new_key = register_number if k == register_value else k
                new_val = _transform(v) if isinstance(v, (dict, list)) else v
                new_dict[new_key] = new_val
            return new_dict
        if isinstance(obj, list):
            return [ _transform(item) if isinstance(item, (dict, list)) else item for item in obj ]
        return obj

    return _transform(flow_params)

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    def _replace_in_dict(d):
        keys_to_replace = [k for k in d if k == register_value]
        for k in keys_to_replace:
            val = d.pop(k)
            d[str(register_number)] = val
        # Recursively process nested dictionaries
        for v in d.values():
            if isinstance(v, dict):
                _replace_in_dict(v)

    if isinstance(flow_params, dict):
        _replace_in_dict(flow_params)
    return flow_params

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number
    """
    def _replace(obj):
        if isinstance(obj, dict):
            # We need to iterate over a copy of the keys because we may modify the dict
            for key in list(obj.keys()):
                if key == register_value:
                    # Rename the key to the register number
                    obj[register_number] = obj[key]
                    del obj[key]
                else:
                    _replace(obj[key])
        elif isinstance(obj, list):
            for item in obj:
                _replace(item)

    _replace(flow_params)
    return flow_params

