def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.
    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import sys
    import shlex

    # Resolve platform value
    if platform == 'this':
        if sys.platform.startswith('win'):
            platform = 0
        else:
            platform = 1

    if platform == 1:
        # POSIX style: use shlex with posix=True for reliable behavior
        return shlex.split(s, posix=True)
    elif platform == 0:
        # Windows/CMD style: a stripped-down regex based split
        # Recognize words, double-quoted strings, single-quoted strings
        # Backslashes inside quotes are preserved unless escaping a quote.
        regex = r'''((?:[^ \\\t"']+|'(?:\\.|[^'])*'|"(?:(?:\\.)|[^"])*")+)'''
        parts = re.findall(regex, s)
        result = []
        for fragment in parts:
            # Remove surrounding quotes if present
            if fragment[0] in ('"', "'") and fragment[-1] == fragment[0]:
                qu = fragment[0]
                inner = fragment[1:-1]
                # Unescape backslash-escaped characters (minimal handling)
                inner = inner.replace(f'\\{qu}', qu).replace('\\\\', '\\')
                result.append(inner)
            else:
                result.append(fragment)
        return result
    else:
        raise ValueError("Unsupported platform value: %s" % platform)

