def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import sys
    if platform == 'this':
        mode = 0 if sys.platform.startswith('win') else 1
    else:
        mode = platform

    if not s:
        return []

    if mode == 0:   # Windows
        # Remove leading/trailing whitespace
        s = s.strip()
        tokens = []
        pattern = r'''(?:(?:"([^"\\]*(?:\\.[^"\\]*)*)")|([^"\s]+))'''
        for m in re.finditer(pattern, s):
            if m.group(1) is not None:
                token = m.group(1)
                # Unescape backslash-escaped characters
                token = token.encode('utf-8').decode('unicode_escape')
                tokens.append(token)
            else:
                tokens.append(m.group(2))
        return tokens
    else:  # POSIX
        pattern = r'''(?:"([^"]*)"|'([^']*)'|(\S+))'''
        tokens = []
        for m in re.finditer(pattern, s):
            if m.group(1) is not None:
                tokens.append(m.group(1))
            elif m.group(2) is not None:
                tokens.append(m.group(2))
            else:
                tokens.append(m.group(3))
        return tokens

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import os
    import subprocess

    # Determine a suitable directory name inside tmp_path
    base_name = os.path.basename(archive_path)
    # Strip common compressed archive suffixes
    for suffix in ('.tar.gz', '.tgz', '.tar.bz2', '.zip'):
        if base_name.endswith(suffix):
            base_name = base_name[: -len(suffix)]
            break
    else:
        base_name = os.path.splitext(base_name)[0]

    # Destination directory for extracted files
    dest_dir = os.path.join(tmp_path, base_name)
    os.makedirs(dest_dir, exist_ok=True)

    # Construct extraction command based on archive type
    if archive_path.endswith('.tar.gz') or archive_path.endswith('.tgz'):
        cmd = ['tar', '-xzf', archive_path, '-C', dest_dir]
    elif archive_path.endswith('.tar.bz2'):
        cmd = ['tar', '-xjf', archive_path, '-C', dest_dir]
    elif archive_path.endswith('.zip'):
        cmd = ['unzip', '-q', '-o', archive_path, '-d', dest_dir]
    else:
        raise ValueError(f'Unsupported archive type for file: {archive_path}')

    # Run the extraction subprocess
    try:
        subprocess.run(cmd, check=True)
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(f"Extraction failed for {archive_path}") from exc

    # Optionally rename the top-level folder if filename is provided
    if filename:
        extracted_path = os.path.join(dest_dir, base_name)
        new_path = os.path.join(dest_dir, filename)
        if not os.path.exists(extracted_path):
            # In some archives the top-level directory might be named differently;
            # use the first non-hidden directory found.
            entries = [e for e in os.listdir(dest_dir) if not e.startswith('.')]
            if entries:
                extracted_path = os.path.join(dest_dir, entries[0])
        if os.path.exists(extracted_path):
            os.rename(extracted_path, new_path)
            dest_dir = new_path

    return f'file://{dest_dir}'

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import os
    import subprocess

    archive_path = os.path.abspath(archive_path)

    if not os.path.isfile(archive_path):
        raise FileNotFoundError(f"Archive does not exist: {archive_path}")

    tmp_root = os.path.abspath(tmp_path)
    if not os.path.isdir(tmp_root):
        os.makedirs(tmp_root, exist_ok=True)

    # Determine the extraction directory name
    if filename:
        out_name = filename
    else:
        base = os.path.basename(archive_path)
        # strip common archive suffixes once
        for suffix in ('.tar.gz', '.tgz', '.tar.bz2', '.tbz2', '.tar.xz', '.tbz', '.zip', '.tar'):
            if base.endswith(suffix):
                out_name = base[: -len(suffix)]
                break
        else:
            # fallback: remove a single extension
            out_name = os.path.splitext(base)[0]

    out_dir = os.path.join(tmp_root, out_name)

    if os.path.exists(out_dir):
        raise FileExistsError(f"Extraction target already exists: {out_dir}")

    os.makedirs(out_dir, exist_ok=True)

    # Choose extraction command based on file extension
    if archive_path.endswith('.tar.gz') or archive_path.endswith('.tgz') \
       or archive_path.endswith('.tar.bz2') or archive_path.endswith('.tbz2') \
       or archive_path.endswith('.tar.xz') or archive_path.endswith('.tar'):
        cmd = ['tar', '-xf', archive_path, '-C', out_dir]
    elif archive_path.endswith('.zip'):
        cmd = ['unzip', '-o', '-q', archive_path, '-d', out_dir]
    elif archive_path.endswith('.tar'):
        cmd = ['tar', '-xf', archive_path, '-C', out_dir]
    else:
        # For single file archives (.gz, .bz2) just decompress in place
        ext = os.path.splitext(archive_path)[1].lower()
        if ext == '.gz':
            cmd = ['gunzip', '-c', archive_path]
        elif ext == '.bz2':
            cmd = ['bunzip2', '-c', archive_path]
        else:
            raise ValueError(f"Unsupported archive type: {archive_path}")

    try:
        subprocess.run(cmd, check=True)
    except subprocess.CalledProcessError as exc:
        # Clean up partially extracted directory
        if os.path.isdir(out_dir):
            try:
                import shutil
                shutil.rmtree(out_dir, ignore_errors=True)
            except Exception:
                pass
        raise RuntimeError(f"Failed to extract {archive_path}") from exc

    return f'file://{out_dir}'

