def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    if isinstance(frequency, str) and frequency.strip().lower() == 'always':
        return None
    if not isinstance(frequency, str):
        raise ValueError('Frequency must be a string, None, or "always"')
    import re
    m = re.fullmatch(r'\s*(?P<num>\d+(?:\.\d+)?)\s*(?P<unit>[a-zA-Z]+)\s*', frequency)
    if not m:
        raise ValueError(f'Could not parse frequency: {frequency!r}')
    num = float(m.group('num'))
    unit = m.group('unit').lower()
    kw = {}
    if unit.startswith('day'):
        kw['days'] = num
    elif unit.startswith('week'):
        kw['weeks'] = num
    elif unit.startswith('hour'):
        kw['hours'] = num
    elif unit.startswith('min'):
        kw['minutes'] = num
    elif unit.startswith('sec'):
        kw['seconds'] = num
    else:
        raise ValueError(f'Unknown time unit in frequency: {unit!r}')
    return datetime.timedelta(**kw)

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or isinstance(frequency, str) and frequency.lower() == 'always':
        return None

    if not isinstance(frequency, str):
        raise ValueError('Frequency must be a string, None, or "always"')

    parts = frequency.strip().lower().split()
    if len(parts) != 2:
        raise ValueError('Frequency must have a number and a unit')

    try:
        quantity = int(parts[0])
    except ValueError:
        raise ValueError('Frequency number must be an integer')

    unit = parts[1]
    # Normalize unit to singular
    if unit.endswith('s'):
        unit = unit[:-1]

    # Map unit to timedelta keyword arguments
    mapping = {
        'day': ('days', 1),
        'week': ('weeks', 1),
        'hour': ('hours', 1),
        'minute': ('minutes', 1),
        'second': ('seconds', 1),
        'month': ('days', 30),   # approximate
        'year': ('days', 365),   # approximate
    }

    if unit not in mapping:
        raise ValueError('Unsupported time unit: %r' % unit)

    kw, multiplier = mapping[unit]
    kwargs = {kw: quantity * multiplier}
    return datetime.timedelta(**kwargs)

