    if host in ('localhost', '127.0.0.1', '::1'):
        return True

    try:
        # Resolve the host to IP addresses
        addrinfo = socket.getaddrinfo(host, None, 0, 0, 0, socket.AI_PASSIVE)
    except socket.gaierror:
        # If the host cannot be resolved, it cannot be localhost
        return False

    # Loopback IP addresses for IPv4 and IPv6
    local_ips = {'127.0.0.1', '::1'}

    for family, _, _, _, sockaddr in addrinfo:
        ip = sockaddr[0]
        if ip in local_ips:
            return True

    return False

