        results = socket.getaddrinfo(host, 0, 0, 0, 0)
    except socket.gaierror:
        return False

    for family, _, _, _, sockaddr in results:
        if family == socket.AF_INET:
            ip = sockaddr[0]
            if ip == "127.0.0.1":
