def subprocess_run_helper(func, *args, timeout, extra_env=None):
    """Run a function in a sub-process."""
    import inspect, os, sys
    if not callable(func):
        raise TypeError("func must be callable")
    mod = inspect.getmodule(func)
    if mod is None or not hasattr(mod, "__file__"):
        raise ValueError("func must be defined in an importable module")
    module_name = mod.__name__
    func_name = func.__name__
    cmd = [
        sys.executable,
        "-c",
        f'import {module_name}; {module_name}.{func_name}()',
    ]
    if args:
        cmd.extend(args)
    env = os.environ.copy()
    if extra_env:
        env.update(extra_env)
    return subprocess.run(cmd, env=env, timeout=timeout)

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:
    """
    if not image_href:
        raise ValueError("Empty image href")
    parsed = urllib.parse.urlparse(image_href)
    if parsed.scheme not in ("http", "https"):
        raise ValueError(f"Unsupported scheme: {parsed.scheme!r}")
    use_ssl = parsed.scheme == "https"
    netloc = parsed.netloc
    if not netloc:
        raise ValueError("Missing network location in URL")
    path = parsed.path
    if not path:
        raise ValueError("Missing path in URL")
    # Grab the last segment of the path
    last_segment = path.rsplit("/", 1)[-1]
    if not last_segment:
        raise ValueError("URL path does not contain a file or identifier")
    # Strip any file extension to get the image ID
    if "." in last_segment:
        image_id, _ = last_segment.rsplit(".", 1)
    else:
        image_id = last_segment
    if not image_id:
        raise ValueError("Could not extract an image id from the URL")
    return image_id, netloc, use_ssl

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:
    """
    if not image_href or not isinstance(image_href, str):
        raise ValueError("image_href must be a non-empty string")
    parsed = urllib.parse.urlparse(image_href)
    # If no scheme and no netloc, treat the string as a bare id or path
    if not parsed.scheme and not parsed.netloc:
        path = image_href.lstrip("/").split("?")[0].split("#")[0]
        if not path:
            raise ValueError(f"Cannot parse image id from '{image_href}'")
        image_id = path.split(".")[0]
        if not image_id:
            raise ValueError(f"Image id not found in '{image_href}'")
        return (image_id, "", False)
    # Netloc present; determine SSL usage
    use_ssl = parsed.scheme.lower() == "https"
    netloc = parsed.netloc
    # Path may start with '/' – remove it
    path = parsed.path.lstrip("/")
    if not path:
        # If there's no path, try to pull an id from the query string as a fallback
        query_params = urllib.parse.parse_qs(parsed.query)
        if not query_params:
            raise ValueError(f"Cannot determine image id from '{image_href}'")
        # Grab the first value from the first query parameter
        for values in query_params.values():
            if values:
                image_id = values[0]
                break
        else:
            raise ValueError(f"Cannot determine image id from '{image_href}'")
    else:
        image_id = path.split(".")[0]
    if not image_id:
        raise ValueError(f"Image id cannot be determined from '{image_href}'")
    return (image_id, netloc, use_ssl)

def get_pattern(pattern, strip=True):
