def get_pattern(pattern, strip=True):
    """
    This method converts the given string to a regex pattern.

    If a string is provided, it is optionally stripped of leading and trailing
    whitespace and then compiled.  If already a compiled pattern is supplied,
    it is returned unchanged.  Any other type raises a TypeError.
    """
    if isinstance(pattern, str):
        if strip:
            pattern = pattern.strip()
        return re.compile(pattern)

    # Determine the compiled regex type on the current runtime
    _pattern_type = type(re.compile(""))
    if not isinstance(pattern, _pattern_type):
        raise TypeError(f"Unsupported pattern type: {repr(pattern)}")

    return pattern

