def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Normalize commands to a list
    if isinstance(commands, str):
        cmd_list = [commands]
    else:
        cmd_list = list(commands)

    # Append any additional arguments
    if args:
        if isinstance(args, list):
            cmd_list.extend(args)
        else:
            cmd_list.append(str(args))

    # Prepare stderr handling
    stderr_option = subprocess.DEVNULL if hide_stderr else None

    # Verbose output
    if verbose:
        print("Executing:", " ".join(cmd_list))
        if cwd:
            print("Working directory:", cwd)
        if env:
            print("Environment variables:", env)

    try:
        completed = subprocess.run(
            cmd_list,
            cwd=cwd,
            env=env,
            capture_output=True,
            text=True,
            stderr=stderr_option,
            check=True
        )
    except subprocess.CalledProcessError as exc:
        # Re-raise with the same type but include command in the message
        raise RuntimeError(f"Command '{' '.join(cmd_list)}' failed with exit code {exc.returncode}") from exc

    # Optional: print stdout if verbose
    if verbose and completed.stdout:
        print(completed.stdout)

    return completed

