def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''

    import os
    import logging
    import json
    import yaml
    import toml

    def _resolve_vars(obj):
        if isinstance(obj, dict):
            return {k: _resolve_vars(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [_resolve_vars(v) for v in obj]
        elif isinstance(obj, str):
            import re
            pattern = re.compile(r'\$\{([^}]+)\}')
            def repl(match):
                var = match.group(1)
                return os.environ.get(var, match.group(0))
            return pattern.sub(repl, obj)
        else:
            return obj

    result_dict = {}
    error_logs = []

    for fname in config_filenames:
        try:
            with open(fname, 'r') as fd:
                raw = fd.read()
            # Detect format by extension
            if fname.lower().endswith('.toml'):
                cfg = toml.loads(raw)
            elif fname.lower().endswith(('.yaml', '.yml')):
                cfg = yaml.safe_load(raw)
            elif fname.lower().endswith('.json'):
                cfg = json.loads(raw)
            else:
                # Fallback: try common formats in order
                try:
                    cfg = toml.loads(raw)
                except Exception:
                    try:
                        cfg = yaml.safe_load(raw)
                    except Exception:
                        cfg = json.loads(raw)
            if overrides:
                if isinstance(cfg, dict):
                    cfg = {**cfg, **overrides}
            if resolve_env:
                cfg = _resolve_vars(cfg)
            result_dict[fname] = cfg
        except Exception as e:
            record = logging.LogRecord(
                name=fname,
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=str(e),
                args=(),
                exc_info=e
            )
            error_logs.append(record)

    return result_dict, error_logs

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    from collections.abc import Mapping, Sequence  # local imports to avoid external modules
    import os
    import json
    import yaml
    import toml
    import re
    import sys

    def _make_log_record(level, msg, exc_info=None):
        """Create a LogRecord with a fixed logger name."""
        return logging.LogRecord(
            name='config_loader',
            level=level,
            pathname='',
            lineno=0,
            msg=msg,
            args=(),
            exc_info=exc_info,
        )

    def _resolve_env_value(val):
        """Recursively replace ${VAR} in strings with environment variables."""
        if isinstance(val, str):
            return re.sub(r'\$\{(\w+)\}', lambda m: os.getenv(m.group(1), ''), val)
        elif isinstance(val, Mapping):
            return {k: _resolve_env_value(v) for k, v in val.items()}
        elif isinstance(val, Sequence) and not isinstance(val, (str, bytes)):
            return [_resolve_env_value(v) for v in val]
        return val

    parsed_configs = {}
    parse_errors = []

    for filename in config_filenames:
        if not os.path.isfile(filename):
            record = _make_log_record(
                level=logging.ERROR,
                msg=f"Configuration file '{filename}' does not exist.",
                exc_info=None,
            )
            parse_errors.append(record)
            continue

        try:
            with open(filename, encoding='utf-8') as fd:
                raw = fd.read()
        except Exception:
            record = _make_log_record(
                level=logging.ERROR,
                msg=f"Error reading configuration file '{filename}'.",
                exc_info=sys.exc_info(),
            )
            parse_errors.append(record)
            continue

        # Determine parser by file extension
        _, ext = os.path.splitext(filename.lower())
        try:
            if ext == '.json':
                cfg = json.loads(raw)
            elif ext in {'.yaml', '.yml'}:
                cfg = yaml.safe_load(raw)
            elif ext == '.toml':
                cfg = toml.loads(raw)
            elif ext == '.ini':
                import configparser
                parser = configparser.ConfigParser()
                parser.read_string(raw)
                cfg = {section: dict(parser.items(section)) for section in parser.sections()}
            else:
                record = _make_log_record(
                    level=logging.ERROR,
                    msg=f"Unsupported configuration file format: '{filename}'.",
                    exc_info=None,
                )
                parse_errors.append(record)
                continue
        except Exception:
            record = _make_log_record(
                level=logging.ERROR,
                msg=f"Error parsing configuration file '{filename}'.",
                exc_info=sys.exc_info(),
            )
            parse_errors.append(record)
            continue

        # Apply overrides, if requested
        if overrides:
            if isinstance(cfg, Mapping):
                cfg = {**cfg, **overrides}
            else:
                record = _make_log_record(
                    level=logging.WARNING,
                    msg=f"Cannot apply overrides to non-dict config in '{filename}'.",
                    exc_info=None,
                )
                parse_errors.append(record)

        # Resolve environment variables
        if resolve_env:
            cfg = _resolve_env_value(cfg)

        parsed_configs[filename] = cfg

    return parsed_configs, parse_errors

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import os
    import yaml
    import re
    try:
        import toml
    except ImportError:
        toml = None

    def _resolve_env(val):
        if isinstance(val, str):
            # replace ${VAR} with environment variable
            def repl(match):
                var = match.group(1)
                return os.getenv(var, '')
            return re.sub(r'\${(\w+)}', repl, val)
        elif isinstance(val, dict):
            return {k: _resolve_env(v) for k, v in val.items()}
        elif isinstance(val, list):
            return [_resolve_env(v) for v in val]
        else:
            return val

    configs = {}
    error_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as fd:
                raw = fd.read()
            # Determine parser based on extension
            if filename.lower().endswith(('.yaml', '.yml')):
                config = yaml.safe_load(raw)
            elif filename.lower().endswith('.toml'):
                if toml is None:
                    raise ImportError('toml package not installed')
                config = toml.loads(raw)
            else:
                # try yaml first, fallback toml
                try:
                    config = yaml.safe_load(raw)
                except Exception:
                    if toml is None:
                        raise
                    config = toml.loads(raw)
        except Exception as exc:
            rec = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Failed to parse {filename}: {exc}',
                args=None,
                exc_info=None
            )
            error_records.append(rec)
            continue

        # Basic validation: must be a dict
        if not isinstance(config, dict):
            rec = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Parsed configuration from {filename} is not a dict (type: {type(config).__name__})',
                args=None,
                exc_info=None
            )
            error_records.append(rec)
            continue

        # Apply overrides if provided
        if overrides:
            try:
                # merge override into config (shallow)
                config.update(overrides)
            except Exception as exc:
                rec = logging.LogRecord(
                    name='config_loader',
                    level=logging.ERROR,
                    pathname=filename,
                    lineno=0,
                    msg=f'Failed to apply overrides to {filename}: {exc}',
                    args=None,
                    exc_info=None
                )
                error_records.append(rec)

        # Resolve environment variables if requested
        if resolve_env:
            try:
                config = _resolve_env(config)
            except Exception as exc:
                rec = logging.LogRecord(
                    name='config_loader',
                    level=logging.WARNING,
                    pathname=filename,
                    lineno=0,
                    msg=f'Environment variable resolution failed for {filename}: {exc}',
                    args=None,
                    exc_info=None
                )
                error_records.append(rec)

        configs[filename] = config

    return configs, error_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    configs = {}
    errors = []

    for fname in config_filenames:
        try:
            with open(fname, 'r') as f:
                raw = f.read()

            if fname.endswith('.toml'):
                import toml
                config = toml.loads(raw)
            elif fname.endswith('.yaml') or fname.endswith('.yml'):
                import yaml
                config = yaml.safe_load(raw)
            elif fname.endswith('.json'):
                import json
                config = json.loads(raw)
            else:
                raise ValueError("Unsupported configuration file format: %s" % fname)

            if config is None:
                config = {}

            if not isinstance(config, dict):
                raise ValueError("Configuration must be a mapping (dict), got %s" % type(config).__name__)

            # Resolve environment variables inside the configuration
            if resolve_env:
                import re, os

                def _resolve(value):
                    if isinstance(value, str):
                        pattern = re.compile(r'\$\{(\w+)\}')
                        return pattern.sub(lambda m: os.getenv(m.group(1), ''), value)
                    elif isinstance(value, dict):
                        return {k: _resolve(v) for k, v in value.items()}
                    elif isinstance(value, list):
                        return [_resolve(v) for v in value]
                    return value

                config = _resolve(config)

            # Apply overrides if provided
            if overrides:
                config.update(overrides)

            configs[fname] = config

        except Exception as exc:
            import logging
            record = logging.LogRecord(
                name='configLoader',
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=str(exc),
                args=(),
                exc_info=(exc.__class__, exc, exc.__traceback__)
            )
            errors.append(record)
            configs[fname] = None

    return configs, errors

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import logging
    import json
    try:
        import yaml
    except ImportError:
        yaml = None
    try:
        import toml
    except ImportError:
        toml = None

    configs = {}
    errors = []

    def _expand_env(value):
        if isinstance(value, str):
            return os.path.expandvars(value)
        if isinstance(value, dict):
            return {k: _expand_env(v) for k, v in value.items()}
        if isinstance(value, list):
            return [_expand_env(v) for v in value]
        return value

    for filename in config_filenames:
        parsed = None
        try:
            with open(filename, 'r', encoding='utf-8') as fd:
                raw = fd.read()

            _, ext = os.path.splitext(filename.lower())
            if ext in ('.yaml', '.yml'):
                if yaml is None:
                    raise ImportError('PyYAML is not installed')
                parsed = yaml.safe_load(raw)
            elif ext == '.toml':
                if toml is None:
                    raise ImportError('Toml is not installed')
                parsed = toml.loads(raw)
            elif ext == '.json':
                parsed = json.loads(raw)
            else:
                # Unknown format: try json as fallback
                parsed = json.loads(raw)

            if parsed is None:
                raise ValueError('Empty configuration')

            if overrides:
                # Apply overrides: shallow merge
                parsed.update(overrides)

            if resolve_env:
                parsed = _expand_env(parsed)

        except Exception as exc:
            # Create a LogRecord for parse error
            record = logging.LogRecord(
                name=__name__,
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=str(exc),
                args=None,
                exc_info=None
            )
            errors.append(record)
            parsed = None

        configs[filename] = parsed

    return configs, errors

