    def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """

        if protocol_version is not None and not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple or None")

        # Attempt to use a predefined mapping if present
        handlers = getattr(cls, "_protocol_handlers", None)

        if handlers is None:
            # Fall back to introspecting class attributes that look like
            # handler classes with a protocol_version attribute.
            handlers = {}
            for attr in vars(cls).values():
                if isinstance(attr, type) and hasattr(attr, "protocol_version"):
                    ver = getattr(attr, "protocol_version")
                    if isinstance(ver, tuple):
                        handlers[ver] = attr

        # If a specific version was requested, filter the dictionary.
        if protocol_version is not None:
            return {protocol_version: handlers[protocol_version]} if protocol_version in handlers else {}

        # Otherwise return all available handlers
        return handlers.copy()

@classmethod
def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple")
    handlers = {}
    for attr_name, attr_val in cls.__dict__.items():
        # Only consider class objects that expose a _protocol_version attribute.
        if isinstance(attr_val, type) and hasattr(attr_val, "_protocol_version"):
            version = getattr(attr_val, "_protocol_version")
            if protocol_version is None or version == protocol_version:
                handlers[version] = attr_val
    return handlers

@classmethod
def protocol_handlers(cls, protocol_version=None):
    """
    Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    # Retrieve the mapping of protocol versions to handler classes.
    # Expect a class attribute `_handlers` that is a dict mapping
    # tuples (major, minor) to handler classes.
    # If the attribute is missing, default to an empty dict.
    all_handlers = getattr(cls, "_handlers", {})
    if protocol_version is not None:
        if not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple")
        # Return a dictionary with at most one entry for the requested version.
        if protocol_version in all_handlers:
            return {protocol_version: all_handlers[protocol_version]}
        else:
            return {}
    # No specific version requested: return all handlers.
    return dict(all_handlers)

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    # Convert each raw string into a Bookmark instance, skipping empty strings.
    bookmarks = []

    for raw in values:
        if not raw:
            continue

        # Prefer an explicit from_raw classmethod if it exists, otherwise
        # instantiate the Bookmark class with the raw string directly.
        if hasattr(Bookmark, "from_raw"):
            try:
                bookmark = Bookmark.from_raw(raw)
            except Exception:
                # Fallback to direct construction if parsing fails.
                bookmark = Bookmark(raw)
        else:
            bookmark = Bookmark(raw)

        bookmarks.append(bookmark)

    return cls(bookmarks)

