def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Consider something iterable (excluding strings/bytes) as a sequence
    if hasattr(seq, "__iter__") and not isinstance(seq, (str, bytes)):
        return seq, type(seq)
    # Otherwise wrap the value in a list
    derived = [seq]
    return derived, type(derived)

def scale(self, other=None):
    """
    Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`ValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3‑dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Return current scale
    if other is None:
        return getattr(self, "_scale", None)

    # Ensure the new scale is numeric
    if not isinstance(other, (int, float)):
        raise TypeError("Scale value must be numeric")

    current = getattr(self, "_scale", None)
    if current is None or current == 0:
        raise ValueError("Cannot rescale graph with unknown or zero scale")

    # Determine factor for rescaling
    factor = other / current

    # Rescale each field; only the last coordinate is affected.
    # We support both simple array fields and objects with .values/.errors attributes.
    for field in getattr(self, "fields", []):
        # Rescale coordinate data
        if hasattr(field, "values") and isinstance(field.values, (list, tuple)):
            # If values is a sequence, assume last element is the target coordinate
            try:
                field.values[-1] *= factor
            except Exception:
                # Fall back to scalar multiply
                field.values = [v * factor for v in field.values]
        elif hasattr(field, "data") and hasattr(field.data, "size"):
            # Assume last coordinate in the last axis
            if field.data.ndim > 0:
                field.data[..., -1] *= factor
            else:
                field.data *= factor
        elif hasattr(field, "size"):
            # Plain numpy array
            if field.ndim > 0:
                field[..., -1] *= factor
            else:
                field *= factor

        # Rescale errors attached to the field
        if hasattr(field, "errors"):
            # errors can be a list of arrays or a single array
            errors = field.errors
            if isinstance(errors, (list, tuple)):
                for err in errors:
                    if isinstance(err, (list, tuple)):
                        try:
                            err[-1] *= factor
                        except Exception:
                            err = [e * factor for e in err]
                    elif hasattr(err, "size"):
                        if err.ndim > 0:
                            err[..., -1] *= factor
                        else:
                            err *= factor
            elif hasattr(errors, "size"):
                if errors.ndim > 0:
                    errors[..., -1] *= factor
                else:
                    errors *= factor

    # Update the stored scale
    self._scale = other
    return None

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    errors = []

    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(
                    "Candidate '%s' does not provide interface '%s'"
                    % (candidate, iface)
                )
        except Exception as exc:
            errors.append(
                "Error checking providedBy for candidate '%s' on interface '%s': %s"
                % (candidate, iface, exc)
            )

    # import modules lazily
    inspect = __import__("inspect")
    zope = __import__("zope")
    zope_interface = __import__("zope.interface")
    # Universal iterator over names; fallback if not present
    try:
        names_iterable = iface.names()
    except AttributeError:
        names_iterable = list(iface)

    for name in names_iterable:
        # Method checks
        try:
            methods = iface.methods
        except AttributeError:
            methods = {}
        if name in methods:
            if not hasattr(candidate, name):
                errors.append("Missing method '%s'" % name)
                continue
            cand_attr = getattr(candidate, name)
            if not callable(cand_attr):
                errors.append("Attribute '%s' is not callable" % name)
                continue
            # Compare signatures
            try:
                iface_sig = inspect.signature(getattr(iface, name))
                cand_sig = inspect.signature(cand_attr)
                if len(iface_sig.parameters) != len(cand_sig.parameters):
                    errors.append(
                        "Signature mismatch in method '%s': "
                        "expected %d params, got %d"
                        % (name, len(iface_sig.parameters), len(cand_sig.parameters))
                    )
                else:
                    iface_params = list(iface_sig.parameters.values())
                    cand_params = list(cand_sig.parameters.values())
                    for ip, cp in zip(iface_params, cand_params):
                        if (
                            ip.kind != cp.kind
                            or ip.default != cp.default
                            or ip.name != cp.name
                        ):
                            errors.append(
                                "Signature mismatch in method '%s': parameter '%s' differs"
                                % (name, cp.name)
                            )
                            break
            except Exception as exc:
                errors.append(
                    "Error examining signature for method '%s': %s" % (name, exc)
                )
            continue

        # Attribute checks
        try:
            attributes = iface.attributes
        except AttributeError:
            attributes = {}
        if name in attributes:
            if not hasattr(candidate, name):
                errors.append("Missing attribute '%s'" % name)
            continue

    if errors:
        if len(errors) == 1:
            raise zope_interface.Invalid(errors[0])
        raise zope_interface.Invalid("\n".join(errors))

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Determine the list of required attributes from the interface.
    if isinstance(iface, (list, tuple, set)):
        required = list(iface)
    else:
        # Filter out private attributes and non-callables.
        required = [name for name in dir(iface)
                    if not name.startswith('_') and callable(getattr(iface, name, None))]

    missing = []
    for name in required:
        if not hasattr(candidate, name):
            missing.append(name)
            continue
        attr = getattr(candidate, name)
        if not callable(attr):
            missing.append(name)

    if missing:
        raise TypeError(f'{candidate!r} does not implement required methods: {missing}')

    # When tentative is False, perform a stricter check: try instantiating
    # the candidate (if it's a class) and ensure all methods are not abstract.
    if not tentative and isinstance(candidate, type):
        try:
            obj = candidate()
        except Exception as exc:
            raise TypeError(f'Cannot instantiate candidate {candidate!r}: {exc}') from exc
        for name in required:
            method = getattr(obj, name)
            try:
                method()
            except NotImplementedError:
                raise TypeError(f'Abstract method {name} not implemented in {candidate!r}')

    return True

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    # Render the candidate as a class if it is not already one
    subject = candidate if isinstance(candidate, type) else candidate.__class__
    # Gather public attributes/methods from the interface
    iface_symbols = [name for name in dir(iface) if not name.startswith('_')]
    missing = []
    wrong_type = []
    for symbol in iface_symbols:
        if not hasattr(subject, symbol):
            missing.append(symbol)
            continue
        iface_attr = getattr(iface, symbol)
        candidate_attr = getattr(subject, symbol)
        if callable(iface_attr):
            if not callable(candidate_attr):
                wrong_type.append(symbol)
    if missing or wrong_type:
        errors = []
        if missing:
            errors.append('missing: ' + ', '.join(sorted(missing)))
        if wrong_type:
            errors.append('wrong_type: ' + ', '.join(sorted(wrong_type)))
        raise TypeError(f'Candidate {candidate!r} does not satisfy interface {iface.__name__}: '
                        + '; '.join(errors))
    return True

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    # Accept either an instance or a class; use the class for checks
    candidate_cls = candidate if isinstance(candidate, type) else type(candidate)

    # Interface implementation may list required attributes in __dict__
    # Skip private names starting with underscore
    for name, iface_val in iface.__dict__.items():
        if name.startswith('_'):
            continue

        if not hasattr(candidate_cls, name):
            if tentative:
                # On tentative check we skip missing attributes
                continue
            raise AssertionError(
                f"{candidate_cls.__name__} does not provide required attribute {name}"
            )

        cand_attr = getattr(candidate_cls, name)

        # If the interface value is callable (e.g. a function or descriptor)
        # then the candidate implementation must be callable.
        if callable(iface_val):
            if not callable(cand_attr):
                raise TypeError(
                    f"Attribute {name} of {candidate_cls.__name__} is not callable"
                )

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Resolve candidate class if an instance was passed
    if not isinstance(candidate, type):
        candidate = type(candidate)
    # Check if candidate is a subclass of iface
    try:
        is_subclass = issubclass(candidate, iface)
    except Exception:
        is_subclass = False
    if tentative:
        return is_subclass
    if not is_subclass:
        raise TypeError(f"'{candidate.__name__}' does not provide the interface '{iface.__name__}'")
    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__."""
    # If an explicit metaclass was supplied, it must be compatible with all bases.
    if explicit_mc is not None:
        for base in bases:
            base_meta = type(base)
            if not issubclass(base_meta, explicit_mc):
                raise TypeError(
                    f"metaclass conflict: {base_meta.__name__} is not a "
                    f"subclass of explicit metaclass {explicit_mc.__name__}"
                )
        return explicit_mc

    # No explicit metaclass; determine the most derived common metaclass.
    if not bases:
        return type  # default metaclass for new-style classes

    # Collect the metaclass of each base.
    meta_candidates = [type(b) for b in bases]

    # Build the MRO lists for each metaclass candidate.
    mro_lists = [mc.mro() for mc in meta_candidates]

    # Find the first metaclass in the first MRO that is present in all others.
    for candidate in mro_lists[0]:
        if all(candidate in mros for mros in mro_lists[1:]):
            return candidate

    raise TypeError("metaclass conflict: no common metaclass found")

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # If no bases and no explicit, return the default metaclass
    if not bases and explicit_mc is None:
        return type

    # Resolve the most derived metaclass implied by the bases
    if bases:
        base_meta = type(bases[0])
        for base in bases[1:]:
            m = type(base)
            # Skip the base metaclass if it's the default of new style classes
            if m is type:
                continue
            # Pick the more derived between the current accumulator and this base's metaclass
            if issubclass(m, base_meta):
                base_meta = m
            elif not issubclass(base_meta, m):
                # Conflict: the metaclasses are unrelated
                raise RuntimeError(
                    f"metaclass conflict: {base_meta.__name__} vs {m.__name__}"
                )
    else:
        base_meta = type

    # If an explicit metaclass is supplied, it must be compatible
    if explicit_mc is None:
        return base_meta

    if not isinstance(explicit_mc, type):
        raise TypeError("explicit_metaclass must be a type")

    if issubclass(explicit_mc, base_meta):
        return explicit_mc
    if issubclass(base_meta, explicit_mc):
        return base_meta

    raise RuntimeError(
        f"metaclass conflict between explicit {explicit_mc.__name__} "
        f"and base-derived {base_meta.__name__}"
    )

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        metaclass = explicit_mc
    else:
        # Gather metaclasses of the base classes
        mcs = [base.__class__ for base in bases if isinstance(base, type)]
        if not mcs:
            return type
        # Find the most derived metaclass among the bases
        metaclass = mcs[0]
        for mc in mcs[1:]:
            if issubclass(mc, metaclass):
                metaclass = mc
            elif not issubclass(metaclass, mc):
                raise TypeError("metaclass conflict: %r and %r" % (metaclass, mc))
    if not isinstance(metaclass, type):
        raise TypeError("%r is not a metaclass type" % metaclass)
    return metaclass

