    """Remove and return the `(key, value)` pair least frequently used."""
    if not hasattr(self, "_cache") or not self._cache:
        raise KeyError("dict is empty")
    if not hasattr(self, "_freq") or not self._freq:
        raise KeyError("frequency data missing")
    # Find the key with the minimum frequency count
    key_to_remove = min(self._freq, key=lambda k: self._freq.get(k, float('inf')))
    # Retrieve and remove the corresponding value
    value = self._cache.pop(key_to_remove, None)
    # Remove the frequency entry
    self._freq.pop(key_to_remove, None)
    return (key_to_remove, value)

