    """
    result = []
    dirs = settings_dirs if isinstance(settings_dirs, (list, tuple, set)) else [settings_dirs]
    for d in dirs:
        try:
            for f in os.listdir(d):
                if f.endswith(spec_option):
                    result.append(os.path.join(d, f))
        except (OSError, FileNotFoundError):
