def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    import os
    import fnmatch
    matched_files = []
    for directory in settings_dirs:
        try:
            for fname in os.listdir(directory):
                if fnmatch.fnmatch(fname, spec_option):
                    matched_files.append(os.path.join(directory, fname))
        except OSError:
            # skip directories that cannot be accessed
            continue
    return sorted(matched_files)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type"""
    file_names = []
    # Accept a single extension string or a list/tuple of extensions
    extensions = (spec_option,)
    if isinstance(spec_option, (list, tuple, set)):
        extensions = spec_option
    for directory in settings_dirs:
        try:
            for fname in os.listdir(directory):
                if any(fname.endswith(ext) for ext in extensions):
                    file_names.append(os.path.join(directory, fname))
        except OSError:
            # If the directory cannot be accessed, simply skip it
            continue
    return sorted(file_names)

