def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files. """
        # First pass: handle any includes at the current level
        for key, val in list(parser_dict.items()):
            if isinstance(val, dict) and 'include' in val:
                include_items = val.pop('include')
                # Normalize to a list of keys
                if isinstance(include_items, str):
                    include_items = [include_items]
                elif not isinstance(include_items, (list, tuple)):
                    continue  # nothing to include
                merged = {}
                for inc_key in include_items:
                    inc_def = parser_dict.get(inc_key)
                    if inc_def is None:
                        # silently ignore missing includes
                        continue
                    if isinstance(inc_def, dict):
                        merged.update(inc_def)
                # Merge the rest of the current dict values after removal
                merged.update(val)
                parser_dict[key] = merged
        # Recursive pass for nested dictionaries
        for val in parser_dict.values():
            if isinstance(val, dict):
                self._include_groups(val)

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    for group_name, group_cfg in list(parser_dict.items()):
        if not isinstance(group_cfg, dict):
            continue
        includes = group_cfg.pop('include', {})
        if not isinstance(includes, dict):
            continue
        for inc_name, inc_cfg in includes.items():
            inc_spec = parser_dict.get(inc_name, inc_cfg)
            if isinstance(inc_spec, dict):
                group_cfg.update(inc_spec)
    return parser_dict

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    # Recursively merge included parser definitions into each parser entry.
    def _merge(target_key, visited):
        if target_key in visited:
            return
        visited.add(target_key)
        cfg = parser_dict.get(target_key, {})
        # Extract the include directive if present.
        inc = cfg.pop('include', None)
        if not inc:
            parser_dict[target_key] = cfg
            return
        # Normalize expose include list or dict to a list of keys to include.
        if isinstance(inc, dict):
            inc_keys = [k for k, v in inc.items() if v]
        else:
            inc_keys = list(inc)
        for inc_key in inc_keys:
            if inc_key not in parser_dict:
                continue
            _merge(inc_key, visited)
            inc_cfg = parser_dict[inc_key]
            # Merge inc_cfg into cfg without overwriting existing keys.
            for k, v in inc_cfg.items():
                if k not in cfg:
                    cfg[k] = v
        parser_dict[target_key] = cfg

    for key in list(parser_dict.keys()):
        _merge(key, set())

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    for key, spec in parser_dict.items():
        # Only try to include if this parser spec is a dict
        if not isinstance(spec, dict):
            continue

        if 'include' not in spec:
            continue

        inc = spec.pop('include')
        # Gather the items that need to be merged in this spec
        merge_items = {}

        # Case 1: include is a dictionary of items to merge
        if isinstance(inc, dict):
            merge_items.update(inc)

        # Case 2: include is a string referring to another key in parser_dict
        elif isinstance(inc, str):
            if inc in parser_dict:
                merge_items.update(parser_dict[inc])
            else:
                raise KeyError(f"Include key '{inc}' not found in parser_dict")

        # Case 3: include is a sequence of keys
        elif isinstance(inc, (list, tuple, set)):
            for inc_key in inc:
                if inc_key in parser_dict:
                    merge_items.update(parser_dict[inc_key])
                else:
                    raise KeyError(f"Include key '{inc_key}' not found in parser_dict")

        else:
            raise TypeError(f"Unsupported include type: {type(inc)} for key '{key}'")

        # Merge gathered items into the current spec
        spec.update(merge_items)
    return parser_dict

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    def _resolve(d):
        if isinstance(d, dict):
            # Check for an 'include' directive
            if 'include' in d:
                inc = d.pop('include')
                # Resolve from file(s) or use the dict directly
                if isinstance(inc, str):
                    inc_dict = self._load_file(inc)
                elif isinstance(inc, list):
                    inc_dict = {}
                    for inc_file in inc:
                        inc_dict.update(self._load_file(inc_file))
                else:
                    inc_dict = inc
                # Merge the included dictionary into the current one
                for key, val in inc_dict.items():
                    if key in d and isinstance(d[key], dict) and isinstance(val, dict):
                        # Recursively merge nested dictionaries
                        d[key].update(val)
                    else:
                        d[key] = val
            # Recursively resolve nested structures
            for value in d.values():
                _resolve(value)
        elif isinstance(d, list):
            for item in d:
                _resolve(item)

    _resolve(parser_dict)
    return parser_dict

