            pass

        # Merge defaults from the spec object if present
        spec = getattr(self, 'spec', None)
        if spec is not None:
            if hasattr(spec, 'defaults'):
                defaults.update(spec.defaults)
            elif hasattr(spec, 'to_dict'):
                defaults.update(spec.to_dict())
            elif hasattr(spec, '__dict__'):
                defaults.update(spec.__dict__)

        # Merge defaults from the default_spec if present
        default_spec = getattr(self, '_default_spec', None)
        if default_spec is not None:
            if hasattr(default_spec, 'defaults'):
                defaults.update(default_spec.defaults)
            elif hasattr(default_spec, 'to_dict'):
                defaults.update(default_spec.to_dict())
            elif hasattr(default_spec, 'items'):
                defaults.update(dict(default_spec.items()))

        return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            raise errors.InvalidSchemeError('Unable to resolve non-Option type')
        # Prefer a value supplied via the spec, otherwise fall back to the option's default
        if hasattr(self, 'spec') and getattr(self.spec, 'get', None) is not None:
            val = self.spec.get(arg.name)
        else:
            val = None
        if val is None:
            # A spec did not provide a value: use the declared default if any
            if not isinstance(arg.default, NoDefault):
                val = arg.default
        # If the option is a DictOption with an embedded scheme,
        # recursively gather defaults for its nested arguments.
        if isinstance(arg, DictOption) and arg.scheme:
            nested = arg.scheme.get_spec_defaults()
            if nested:
                val = nested
        defaults[arg.name] = val
    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            continue

        # Get value from spec if present
        try:
            if isinstance(self.spec, dict):
                if arg.name in self.spec:
                    defaults[arg.name] = self.spec[arg.name]
                    continue
            else:
                val = getattr(self.spec, arg.name, None)
                if val is not None:
                    defaults[arg.name] = val
                    continue
        except Exception:
            # If spec is not accessible, skip to fallback
            pass

        # Fallback to argument's own default value
        if not isinstance(arg.default, NoDefault):
            defaults[arg.name] = arg.default

        # For nested DictOption, merge defaults from its scheme
        if isinstance(arg, DictOption) and arg.scheme:
            nested = arg.scheme.get_spec_defaults()
            if nested:
                defaults[arg.name] = nested
    return defaults

def get_spec_defaults(self):
