def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            continue

        # Prefer value from the spec if present
        value = getattr(self.spec, arg.name, None)

        # If spec does not provide value, fall back to the option default
        if value is None:
            if not isinstance(arg.default, NoDefault):
                value = arg.default
            # For dict options, use the scheme's defaults if needed
            elif isinstance(arg, DictOption) and arg.scheme:
                value = arg.scheme.build_defaults()

        # Handle nested dict option: merge spec values with scheme defaults
        if isinstance(arg, DictOption) and isinstance(value, dict) and arg.scheme:
            scheme_defaults = arg.scheme.build_defaults()
            # Spec values should override scheme defaults
            scheme_defaults.update(value)
            value = scheme_defaults

        defaults[arg.name] = value
    return defaults

