    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Expect the subclass to define a ``deprecated_args`` attribute which contains
    # the names of all deprecated arguments.  If the attribute is missing or empty
    # we simply do nothing.
    deprecated = getattr(self, 'deprecated_args', set())
    if not deprecated:
        return

    # Check each source of arguments and report any deprecated keys.
    for source_name, args in [('cli_args', cli_args), ('answer_file_args', answer_file_args)]:
        for key in args:
            if key in deprecated:
                print(f"Deprecated argument '{key}' detected in {source_name}.")

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Merge the provided dictionaries, giving precedence to CLI arguments.
    combined_args = {**answer_file_args, **cli_args}

    # The mapping of deprecated argument names to their replacements.
    deprecated_map = getattr(self, 'deprecated_args', {})
    # Some implementations may store a list of deprecated arguments without replacement.
    deprecated_list = getattr(self, 'deprecated_args_list', [])

    for old_arg, new_arg in deprecated_map.items():
        if old_arg in combined_args:
            print(f"Deprecated argument '{old_arg}' detected. Use '{new_arg}' instead.")

    for old_arg in deprecated_list:
        if old_arg in combined_args:
            print(f"Deprecated argument '{old_arg}' detected. No replacement available.")

def validate_arg_deprecation(self, cli_args, answer_file_args):
