def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    if not command_name:
        raise ValueError("command_name must be provided")
    # Retrieve the command options dictionary.  The actual storage
    # location may vary (e.g. _options, _cmd_options).  We look for a
    # few common attribute names to maximize compatibility.
    opts_dict = None
    for attr in ("_options", "_cmd_options", "_command_options"):
        if hasattr(self, attr):
            opts_dict = getattr(self, attr)
            break
    if opts_dict is None or not isinstance(opts_dict, dict):
        raise AttributeError("Option specifications are not available")
    cmd_opts = opts_dict.get(command_name, {})
    spec = cmd_opts.get(argument_name)
    if spec is None:
        raise KeyError(f"Option '{argument_name}' not found for command '{command_name}'")
    return spec

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Locate the mapping that contains all command specifications
    if hasattr(self, "commands"):
        cmd_specs = self.commands
    elif hasattr(self, "command_specs"):
        cmd_specs = self.command_specs
    else:
        raise AttributeError("No command specification storage found on this instance")

    # Ensure the requested command exists
    if command_name not in cmd_specs:
        raise KeyError(f"Command '{command_name}' not found in specifications")

    # Retrieve the option mapping for the given command
    spec_map = cmd_specs[command_name]
    if not isinstance(spec_map, dict):
        raise TypeError(f"Specification for command '{command_name}' must be a dict mapping option names to specs")

    # Return the requested option's specification
    if argument_name not in spec_map:
        raise KeyError(f"Option '{argument_name}' not defined for command '{command_name}'")
    return spec_map[argument_name]

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Prefer a dedicated option specification dictionary if it exists
    if hasattr(self, "_option_specs"):
        command_spec = self._option_specs.get(command_name, {})
        if isinstance(command_spec, dict):
            return command_spec.get(argument_name)

    # Fallback to a generic commands mapping
    if hasattr(self, "commands"):
        cmd = self.commands.get(command_name)
        if isinstance(cmd, dict):
            return cmd.get(argument_name)

    # If we cannot find the command or option, return None
    return None

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    # Interpret silent arguments as those flags that were set.
    silent_args = []

    # If args is an argparse.Namespace, iterate over its attributes.
    if hasattr(args, "__dict__"):
        for name, value in vars(args).items():
            # Treat boolean flags that are True as silent.
            if isinstance(value, bool) and value:
                silent_args.append(name)
        return silent_args

    # Otherwise assume args is an iterable of strings (e.g., a list of argv).
    for item in args:
        if isinstance(item, str) and item.startswith('-'):
            # Strip leading dashes to return the flag name.
            silent_args.append(item.lstrip('-'))
    return silent_args

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    # Determine if args is a mapping (e.g., argparse.Namespace or dict). If it is a Namespace
    # we can obtain its __dict__ representation, otherwise assume it is a dict-like object.
    if hasattr(args, '__dict__'):
        args_dict = args.__dict__
    elif isinstance(args, dict):
        args_dict = args
    else:
        # If args is an iterable of (key, value) tuples
        try:
            args_dict = dict(args)
        except Exception:
            args_dict = {}

    # Return names of arguments that are considered "silent" (typically prefixed with '_' or '_' repeated).
    silent_args = [name for name in args_dict if isinstance(name, str) and name.startswith('_')]
    return silent_args

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Determine which arguments are required. By convention, the class
    # should expose a ``required_args`` iterable containing the names of
    # arguments that must be present. If it is not defined we simply
    # consider there are no required arguments and return.
    required = getattr(self, "required_args", [])
    if not required:
        return

    # Normalise the source of arguments.  ``args`` may be a plain dict
    # or an argparse.Namespace (or any object exposing attributes).
    def get_value(name):
        if isinstance(args, dict):
            return args.get(name)
        return getattr(args, name, None)

    missing = [name for name in required if get_value(name) is None]
    if missing:
        missing_str = ", ".join(missing)
        raise ValueError(f"Missing required argument(s): {missing_str}")

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    required = getattr(self, 'required_args', None) or getattr(self, 'required', None) or getattr(self, '_required', None)
    if not required:
        return
    missing = [arg for arg in required if arg not in args or args[arg] is None]
    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    required = getattr(self, 'required_args', [])
    if not isinstance(required, (list, tuple)):
        raise ValueError("required_args must be a list or tuple of argument names")
    missing = [name for name in required if name not in args or args[name] is None]
    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    # Helper function to evaluate a condition that can be a callable or an
    # expression string.
    def _eval_condition(cond, cmd, argdict):
        try:
            if callable(cond):
                # Try to call with (command_name, args) first then with args only
                try:
                    return bool(cond(cmd, argdict))
                except TypeError:
                    return bool(cond(argdict))
            else:
                # Treat as string expression
                return bool(eval(cond, {}, {"command_name": cmd, "args": argdict}))
        except Exception:
            return False

    for opt in options_spec:
        # Determine the option's name/key.
        opt_name = None
        if isinstance(opt, dict):
            for nkey in ("name", "arg", "id"):
                if nkey in opt:
                    opt_name = opt[nkey]
                    break
        else:
            # Assume sequence-like where first element is name.
            try:
                opt_name = opt[0]
            except Exception:
                pass

        if not opt_name:
            continue

        required_when = None
        if isinstance(opt, dict):
            required_when = opt.get("required_when")

        if required_when is None:
            continue

        if _eval_condition(required_when, command_name, args):
            required.append(opt_name)

    return required

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    for option in options_spec:
        cond = option.get('required_when')
        if not cond:
            continue
        try:
            # try passing both command_name and args first
            try:
                result = cond(command_name, args)
            except TypeError:
                # fallback: just pass args
                result = cond(args)
        except Exception:
            # If the condition callable raises, ignore this option
            continue

        if result:
            required.append(option.get('name'))
    return required

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    # Ensure args is a dict for key lookup; if it's not, try to convert
    if not isinstance(args, dict):
        try:
            args = dict(args)
        except Exception:
            args = {}

    for opt in options_spec:
        # Each option is expected to have 'arguments' key containing a list
        for arg in opt.get('arguments', []):
            if 'required_when' not in arg:
                continue
            cond = arg['required_when']
            matched = False
            try:
                if callable(cond):
                    matched = bool(cond(args))
                elif isinstance(cond, str):
                    # treat string as name of argument that must be truthy
                    matched = bool(args.get(cond))
                elif isinstance(cond, (list, tuple)):
                    # all conditions should be true
                    matched = all(
                        (bool(args.get(c)) if isinstance(c, str) else
                         bool(c(args)) if callable(c) else False)
                        for c in cond
                    )
                else:
                    matched = bool(cond)
            except Exception:
                matched = False
            if matched:
                required.append(arg.get('name'))
    return required

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    required = []
    for opt in options_spec:
        req_cond = opt.get('required_when')
        if req_cond is None:
            continue
        matched = False
        if callable(req_cond):
            try:
                matched = bool(req_cond(command_name, args))
            except TypeError:
                try:
                    matched = bool(req_cond(command_name))
                except TypeError:
                    matched = bool(req_cond(args))
        else:
            if isinstance(req_cond, bool):
                matched = req_cond
            elif isinstance(req_cond, (list, tuple, set)):
                matched = command_name in req_cond
            else:
                matched = bool(req_cond)
        if matched:
            name = opt.get('name')
            if name is not None:
                required.append(name)
    return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    parsed_args = self.parsed_yaml.get('args', {})
    for arg_name, value in args.items():
        arg_spec = parsed_args.get(arg_name)
        if arg_spec is None:
            continue
        max_len = arg_spec.get('max_length')
        if max_len is None:
            continue
        try:
            length = len(value)
        except TypeError:
            # If value has no length, skip this check
            continue
        if length > max_len:
            self.abort(
                f"Argument '{arg_name}' is longer than allowed maximum length {max_len} (got length {length})"
            )

def validate_length_args(self, args):
    """
    Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Retrieve argument definitions from parsed yaml. They can be stored either
    # as a dict or as a list of single‑item dicts (to allow multiple positional
    # args). Build a mapping of argument name -> maximum allowed length.
    arg_defs = self.parsed_yaml.get('args', {})
    max_len_map = {}

    if isinstance(arg_defs, dict):
        for name, attrs in arg_defs.items():
            if isinstance(attrs, dict) and 'length' in attrs:
                max_len_map[name] = attrs['length']
    elif isinstance(arg_defs, list):
        for item in arg_defs:
            if isinstance(item, dict):
                for name, attrs in item.items():
                    if isinstance(attrs, dict) and 'length' in attrs:
                        max_len_map[name] = attrs['length']

    # Validate each supplied argument against its defined maximum length
    for name, value in args.items():
        max_len = max_len_map.get(name)
        if max_len is None:
            continue

        # Try to determine the size of the value; if this fails we skip
        # validation for that value (e.g. non‑sized objects).
        try:
            length_of_value = len(value)
        except Exception:
            continue

        if length_of_value > max_len:
            abort(f"Argument '{name}' exceeds maximum length of {max_len}")

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Ensure args is a list or dict
    path = []
    self._assert_struct_type(args, 'args', (dict, list), path)

    # Helper to validate a single argument dict
    def _validate_one(arg_name, arg_attrs):
        maxlen = arg_attrs.get('maxlen')
        if maxlen is None:
            return
        value = arg_attrs.get('value')
        if value is None:
            return
        try:
            actual_len = len(value)
        except TypeError:
            raise TypeError(f"Argument '{arg_name}' value has no length property")
        if actual_len > maxlen:
            raise ValueError(
                f"Argument '{arg_name}' length {actual_len} exceeds the allowed {maxlen}"
            )

    if isinstance(args, dict):
        for arg_name, arg_attrs in args.items():
            _validate_one(arg_name, arg_attrs)
    else:
        # args is a list of single-key dicts
        for argdict in args:
            self._assert_command_dict(argdict, '[list-item]', path)
            # Each dict has a single key
            arg_name, arg_attrs = list(argdict.items())[0]
            _validate_one(arg_name, arg_attrs)

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified."""
    arg_specs = self.parsed_yaml.get('args', {})
    for arg_name, spec in arg_specs.items():
        # Find a key that specifies the maximum allowed length
        max_len = None
        for key in ('length', 'max_length', 'max_len', 'maxlength'):
            if key in spec:
                max_len = spec[key]
                break
        if max_len is None:
            continue
        # Validate that the max_len value itself is a non-negative integer
        if not isinstance(max_len, int) or max_len < 0:
            raise ValueError(
                f"Invalid length constraint for argument '{arg_name}': {max_len!r}")
        # Retrieve the actual argument value
        value = args.get(arg_name)
        if value is None:
            continue
        # Check if the value has a length attribute
        try:
            val_len = len(value)
        except TypeError:
            # Value is not sized (e.g., int, float); skip length check
            continue
        if val_len > max_len:
            raise ValueError(
                f"Argument '{arg_name}' length {val_len} exceeds maximum of {max_len} from specification")
    return None

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dict")
    # Retrieve the argument specifications from the parsed YAML configuration.
    argspec = getattr(self, "parsed_yaml", {}).get("args", {})
    for arg_name, arg_value in args.items():
        spec = argspec.get(arg_name, {})
        # The spec may provide a max length under 'max_length' or 'length'.
        max_len = spec.get("max_length") if "max_length" in spec else spec.get("length")
        if max_len is None:
            continue  # no length restriction for this argument
        try:
            val_len = len(arg_value)
        except TypeError:
            continue  # argument value is not sized; skip length check
        if val_len > max_len:
            raise ValueError(
                f"Argument '{arg_name}' length {val_len} exceeds maximum allowed {max_len}"
            )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Retrieve argument specifications from the parsed YAML configuration
    arg_defs = self.parsed_yaml.get('args', {})
    for arg_name, value in args.items():
        # Skip arguments that are not defined in the specification
        arg_def = arg_defs.get(arg_name)
        if not arg_def:
            continue
        # Handle normal case where the argument definition is a dict
        if isinstance(arg_def, dict):
            choices = arg_def.get('choices')
            if choices is not None and value not in choices:
                abort(
                    f"Argument '{arg_name}' has invalid value {value!r}. "
                    f"Allowed choices: {choices}"
                )
        # Handle legacy case where arg_def might be a list of single mapping
        elif isinstance(arg_def, list) and arg_def:
            choices = arg_def[0].get('choices')
