                        f"Argument `{arg_name}` has invalid value {value!r}. "
                        f"Allowed choices are: {allowed!r}"
                    )
        else:
            # Fallback: treat as a single value that must equal the allowed
            if value != allowed:
                abort(
                    f"Argument `{arg_name}` has invalid value {value!r}. "
                    f"Expected: {allowed!r}"
