        # Determine the allowed min and max for the given argument
        if hasattr(self, 'valid_range'):
            rng = getattr(self, 'valid_range')
            if not (isinstance(rng, (list, tuple)) and len(rng) == 2):
                raise ValueError("valid_range must be a two-element sequence")
            min_val, max_val = rng
        elif hasattr(self, 'valid_min') and hasattr(self, 'valid_max'):
            min_val = getattr(self, 'valid_min')
            max_val = getattr(self, 'valid_max')
        else:
            raise ValueError(f"No valid_min/valid_max or valid_range defined for argument '{name}'")

        # Perform comparison, handling string comparisons separately
        try:
            if isinstance(value, str) or isinstance(min_val, str) or isinstance(max_val, str):
                # For string values, use natural ordering
                if value < min_val or value > max_val:
                    raise ValueError(f"Argument '{name}' value '{value}' must be between '{min_val}' and '{max_val}'")
