            raise TypeError(f"Cannot compare values for argument '{name}': {exc}") from exc
    return args

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    import collections
    import argparse

    # The specification should provide at least a list of field names
    fields = spec_option.get('fields')
    if not isinstance(fields, (list, tuple)):
        raise ValueError('spec_option must contain a "fields" list or tuple')

    # Create a namedtuple type to represent the complex value
    cls = collections.namedtuple(type_name, fields)

    # Helper to parse a user supplied string into the namedtuple
    def parse(value):
        # Expect comma-separated key=value pairs
        parts = value.split(',')
        kwargs = {}
        for part in parts:
            if '=' not in part:
                raise argparse.ArgumentTypeError(
                    f'Invalid format for {option_name} (subcommand "{subcommand}"): {value}'
                )
            key, val = part.split('=', 1)
            key = key.strip()
            val = val.strip()
            if key not in fields:
                raise argparse.ArgumentTypeError(
                    f'Unknown field "{key}" for {option_name} (subcommand "{subcommand}")'
                )
            kwargs[key] = val

        # Apply defaults and validate required fields
        defaults = spec_option.get('defaults', {})
        for f in fields:
            if f not in kwargs:
                if f in defaults:
                    kwargs[f] = defaults[f]
                else:
                    raise argparse.ArgumentTypeError(
                        f'Missing required field "{f}" for {option_name} (subcommand "{subcommand}")'
                    )

        return cls(**kwargs)

    return parse

