def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of arguments to be updated in place
    """
    if not values_dict:
        return

    # Attempt to get parser-specific converters if defined
    converters = getattr(self, f"{parser_name}_converters", {})
    # Fallback to a generic converters dictionary if available
    if not converters and hasattr(self, "converters"):
        converters = getattr(self, "converters", {})

    for key, val in list(values_dict.items()):
        # Use a custom converter if one exists
        conv = converters.get(key)
        if conv:
            try:
                values_dict[key] = conv(val)
                continue
            except Exception:
                # Preserve original if conversion fails
                pass

        # Default conversions for common types if the value is a string
        if isinstance(val, str):
            # Try integer conversion
            try:
                values_dict[key] = int(val)
                continue
            except ValueError:
                pass
            # Try float conversion
            try:
                values_dict[key] = float(val)
                continue
            except ValueError:
                pass
            # Try boolean conversion
            if val.lower() in ("true", "false"):
                values_dict[key] = val.lower() == "true"

    return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Retrieve the option specification for the given parser. This map should
    # map option names to objects containing type information.
    # The implementation assumes that `self._parsers` (or a similar attribute)
    # holds parsers indexed by name. Each parser in turn exposes a mapping
    # `options` from option names to option descriptors.
    parser_spec = getattr(self, "_parsers", {}).get(parser_name)
    if not parser_spec:
        # If no parser is found, nothing to convert
        return

    # Option descriptor might be an argparse.Action, a custom object,
    # or a simple dict with a 'type' key.  Handle each case generically.
    for opt_name, opt_value in list(values_dict.items()):
        option = parser_spec.get(opt_name)
        if not option:
            continue

        # Determine the expected type
        expected_type = None
        if hasattr(option, "type") and option.type is not None:
            expected_type = option.type
        elif isinstance(option, dict) and "type" in option:
            expected_type = option["type"]

        # If no type information available, skip conversion
        if expected_type is None:
            continue

        # Perform conversion, handling booleans specially
        try:
            if expected_type is bool:
                if isinstance(opt_value, str):
                    values_dict[opt_name] = opt_value.lower() in {"1", "true", "yes", "on"}
                else:
                    values_dict[opt_name] = bool(opt_value)
            else:
                values_dict[opt_name] = expected_type(opt_value)
        except Exception:
            # If conversion fails, leave the original value untouched
            pass

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    import yaml

    flat_dict = {}

    # Helper to recursively flatten dictionaries
    def _flatten(d, parent_key=""):
        for key, value in d.items():
            new_key = f"{parent_key}.{key}" if parent_key else key
            if isinstance(value, dict):
                _flatten(value, new_key)
            else:
                flat_dict[new_key] = value

    # Walk through all files in the directory
    for root, _, files in os.walk(plugin_dir):
        for fname in files:
            file_path = os.path.join(root, fname)
            ext = os.path.splitext(fname)[1].lower()
            try:
                if ext == ".json":
                    with open(file_path, "r", encoding="utf-8") as fh:
                        data = json.load(fh)
                elif ext in {".yaml", ".yml"}:
                    with open(file_path, "r", encoding="utf-8") as fh:
                        data = yaml.safe_load(fh)
                else:
                    continue
            except Exception:
                # Skip files that can't be parsed
                continue

            if isinstance(data, dict):
                _flatten(data)
    return flat_dict

