    # Search for a json specification file in the directory
    spec_path = None
    for fname in os.listdir(plugin_dir):
        if fname.lower().endswith('.json'):
            spec_path = os.path.join(plugin_dir, fname)
            break

    # If no JSON spec is found, return an empty dict
    if not spec_path:
        return {}

    # Load the JSON spec
    with open(spec_path, 'r', encoding='utf-8') as handle:
        spec = json.load(handle)

    # Recursively flatten nested dictionaries into a single-level dict
    flat_spec = {}

    def _flatten(current, parent_key=''):
        for key, value in current.items():
            new_key = f'{parent_key}.{key}' if parent_key else key
            if isinstance(value, dict):
                _flatten(value, new_key)
            else:
                flat_spec[new_key] = value

    _flatten(spec)
    return flat_spec

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Determine the spec filename
    spec = {}
    for fname in ("plugin.yaml", "plugin.yml", "plugin.json"):
        path = os.path.join(plugin_dir, fname)
        if os.path.isfile(path):
            if fname.endswith((".yaml", ".yml")):
                import yaml
                with open(path, "r", encoding="utf-8") as f:
                    spec = yaml.safe_load(f) or {}
            else:
                with open(path, "r", encoding="utf-8") as f:
                    spec = json.load(f) or {}
            break

    if not isinstance(spec, dict):
        spec = {}

    def _flatten(d, parent_key="", out=None):
        if out is None:
            out = {}
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                _flatten(v, new_key, out)
            else:
                out[new_key] = v
        return out

    return _flatten(spec)

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Determine spec file
    spec_file = None
    for fname in ("plugin.json", "manifest.json", "package.json"):
        candidate = os.path.join(plugin_dir, fname)
        if os.path.isfile(candidate):
            spec_file = candidate
            break

    if not spec_file:
        return {}

    # Load JSON spec
    try:
        with open(spec_file, "r", encoding="utf-8") as f:
            spec = json.load(f)
    except Exception:
        return {}

    # Helper to flatten nested dicts and lists
    def _flatten(obj, parent_key=""):
        items = {}
        if isinstance(obj, dict):
            for k, v in obj.items():
                new_key = f"{parent_key}.{k}" if parent_key else k
                items.update(_flatten(v, new_key))
        elif isinstance(obj, list):
            for i, item in enumerate(obj):
                new_key = f"{parent_key}.{i}" if parent_key else str(i)
                items.update(_flatten(item, new_key))
        else:
            items[parent_key] = obj
        return items

    return _flatten(spec)

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Locate the plugin spec file (support json or yaml)
    spec_path = None
    for fname in ("plugin.json", "plugin.yaml", "plugin.yml"):
        path = os.path.join(plugin_dir, fname)
        if os.path.isfile(path):
            spec_path = path
            break

    if not spec_path:
        return {}

    # load the spec
    try:
        with open(spec_path, "r", encoding="utf-8") as f:
            if spec_path.endswith(".json"):
                spec = json.load(f)
            else:
                # try yaml if available
                try:
                    import yaml
                    spec = yaml.safe_load(f)
                except Exception:
                    spec = {}
    except Exception:
        return {}

    # flatten nested dicts
    def _flatten(d, parent_key="", sep="."):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    return _flatten(spec)

