def extend_cli(self, root_subparsers):
    """
    Adds the spec cli options to to the main entry point.

    :param subparser: the subparser object to extend.
    """
    for name, command in self.commands.items():
        subparser = root_subparsers.add_parser(name, help=getattr(command, "__doc__", ""))
        # If the command knows how to add its CLI options, delegate to it
        if hasattr(command, "add_cli_options") and callable(command.add_cli_options):
            command.add_cli_options(subparser)
        # Fallback: look for a ``cli_options`` attribute that lists argparse arguments
        elif hasattr(command, "cli_options"):
            for opt in command.cli_options:
                if isinstance(opt, tuple):
                    # The tuple may contain args and a kwargs dict
                    if len(opt) > 1 and isinstance(opt[-1], dict):
                        *args, kwargs = opt
                    else:
                        args, kwargs = opt, {}
                    subparser.add_argument(*args, **kwargs)
                else:
                    subparser.add_argument(opt)
        # Attach the command handler so it can be invoked later
        subparser.set_defaults(_handler=command)
